from kazoo.client import KazooClient

class ZooKeeperRangeAllocator:
    def __init__(self, zk_hosts='127.0.0.1:2181', range_size=1000000):
        self.zk = KazooClient(hosts=zk_hosts)
        self.zk.start()
        self.range_size = range_size
        self.range_path = "/url_shortener/global_counter"
        self._ensure_node()

    def _ensure_node(self):
        if not self.zk.exists(self.range_path):
            self.zk.create(self.range_path, b"1000000", makepath=True)

    def get_next_range(self):
        # Atomic compare-and-swap loop to obtain next range window
        while True:
            data, stat = self.zk.get(self.range_path)
            current_val = int(data.decode())
            next_val = current_val + self.range_size
            try:
                self.zk.set(self.range_path, str(next_val).encode(), version=stat.version)
                return current_val, next_val - 1
            except Exception:
                continue # Retry on concurrent collision

