import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class Property {
    String propertyId;
    String name;
    String location;
    double price;
    List<String> amenities;
    double rating;

    public Property(String id, String name, String loc, double price, List<String> amenities, double rating) {
        this.propertyId = id;
        this.name = name;
        this.location = loc;
        this.price = price;
        this.amenities = amenities;
        this.rating = rating;
    }
}

class AgodaBookingService {
    private final Map<String, Property> propertyCatalog = new ConcurrentHashMap<>();
    private final Map<String, Integer> roomInventoryByDate = new ConcurrentHashMap<>();

    public synchronized boolean lockRoomAndBook(String roomIdDateKey) {
        int available = roomInventoryByDate.getOrDefault(roomIdDateKey, 0);
        if (available > 0) {
            roomInventoryByDate.put(roomIdDateKey, available - 1);
            return true; // Reservation success
        }
        return false; // Out of stock
    }

    public List<Property> searchProperties(String location, double maxPrice, List<String> requiredAmenities) {
        List<Property> matched = new ArrayList<>();
        for (Property p : propertyCatalog.values()) {
            if (p.location.equalsIgnoreCase(location) && p.price <= maxPrice && p.amenities.containsAll(requiredAmenities)) {
                matched.add(p);
            }
        }
        return matched;
    }
}

