#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <chrono>
#include <optional>
#include <algorithm>

struct Property {
    std::string propertyId;
    std::string name;
    std::string city;
    double pricePerNight;
    std::vector<std::string> amenities;
    double rating;
};

struct BookingRecord {
    std::string bookingId;
    std::string userId;
    std::string propertyId;
    std::string checkInDate;
    std::string checkOutDate;
    int guests;
    double totalAmount;
    std::string status;
};

class AgodaService {
private:
    std::unordered_map<std::string, Property> properties;
    std::unordered_map<std::string, int> roomInventory; // Key: "propertyId:date" -> Available Rooms
    std::unordered_map<std::string, BookingRecord> bookings;

    mutable std::shared_mutex propertyMutex;
    std::mutex bookingMutex;
    int bookingCounter = 1000;

public:
    void addProperty(const Property& prop) {
        std::unique_lock<std::shared_mutex> lock(propertyMutex);
        properties[prop.propertyId] = prop;
    }

    void setInventory(const std::string& propertyId, const std::string& date, int count) {
        std::lock_guard<std::mutex> lock(bookingMutex);
        roomInventory[propertyId + ":" + date] = count;
    }

    std::vector<Property> searchProperties(const std::string& city, double maxPrice, const std::vector<std::string>& requiredAmenities) const {
        std::shared_lock<std::shared_mutex> lock(propertyMutex);
        std::vector<Property> results;

        for (const auto& [id, prop] : properties) {
            if (prop.city == city && prop.pricePerNight <= maxPrice) {
                bool hasAllAmenities = true;
                for (const auto& req : requiredAmenities) {
                    if (std::find(prop.amenities.begin(), prop.amenities.end(), req) == prop.amenities.end()) {
                        hasAllAmenities = false;
                        break;
                    }
                }
                if (hasAllAmenities) {
                    results.push_back(prop);
                }
            }
        }
        return results;
    }

    std::optional<std::string> createBookingWithAtomicLock(const std::string& userId, const std::string& propertyId,
                                                          const std::string& date, int guests) {
        std::lock_guard<std::mutex> lock(bookingMutex);
        std::string invKey = propertyId + ":" + date;

        // 1. Check Inventory & Prevent Double-Booking
        if (roomInventory.find(invKey) == roomInventory.end() || roomInventory[invKey] <= 0) {
            std::cout << "Booking failed: No rooms available for date: " << date << "\n";
            return std::nullopt;
        }

        // 2. Decrement inventory atomically
        roomInventory[invKey] -= 1;

        // 3. Persist Booking Record
        std::string bId = "BK_" + std::to_string(++bookingCounter);
        bookings[bId] = BookingRecord{bId, userId, propertyId, date, date, guests, 150.0, "CONFIRMED"};

        std::cout << "SUCCESS: Booked " << propertyId << " on " << date << ". Booking ID: " << bId << "\n";
        return bId;
    }
};

int main() {
    AgodaService agoda;
    agoda.addProperty({"prop_101", "Agoda Grand Resort", "Bangkok", 120.0, {"WiFi", "Pool", "Breakfast"}, 4.8});
    agoda.addProperty({"prop_102", "Budget City Inn", "Bangkok", 45.0, {"WiFi"}, 4.0});

    // Set Inventory for 2026-10-10: 1 Room Available
    agoda.setInventory("prop_101", "2026-10-10", 1);

    std::cout << "--- 1. Searching Properties in Bangkok (< $150 with WiFi & Pool) ---\n";
    auto matched = agoda.searchProperties("Bangkok", 150.0, {"WiFi", "Pool"});
    for (const auto& p : matched) {
        std::cout << "Found: " << p.name << " | Price: $" << p.pricePerNight << " | Rating: " << p.rating << "\n";
    }

    std::cout << "\n--- 2. User A Books the Last Room ---\n";
    auto b1 = agoda.createBookingWithAtomicLock("user_A", "prop_101", "2026-10-10", 2);

    std::cout << "\n--- 3. User B Attempts to Book Same Date (Concurrency Collision) ---\n";
    auto b2 = agoda.createBookingWithAtomicLock("user_B", "prop_101", "2026-10-10", 1);

    return 0;
}

