from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict
import uuid

app = FastAPI()
payments_db = {}

class CustomerDetails(BaseModel):
    name: str
    email: str

class PaymentRequest(BaseModel):
    amount: float
    currency: str
    method: str
    customer_details: CustomerDetails

@app.post("/payments")
def create_payment(payment: PaymentRequest, idempotency_key: Optional[str] = Header(None)):
    if idempotency_key and idempotency_key in payments_db:
        return payments_db[idempotency_key]

    pay_id = "pay_" + str(uuid.uuid4())[:8]
    response_data = {
        "payment_id": pay_id,
        "amount": payment.amount,
        "currency": payment.currency,
        "status": "authorized",
        "method": payment.method
    }

    if idempotency_key:
        payments_db[idempotency_key] = response_data
    payments_db[pay_id] = response_data
    return response_data

@app.get("/payments/{payment_id}")
def get_payment(payment_id: str):
    if payment_id in payments_db:
        return payments_db[payment_id]
    raise HTTPException(status_code=404, detail="Payment not found")

@app.post("/payments/{payment_id}/capture")
def capture_payment(payment_id: str, amount: float):
    if payment_id in payments_db:
        payments_db[payment_id]["status"] = "captured"
        return {"payment_id": payment_id, "status": "captured", "amount": amount}
    raise HTTPException(status_code=404, detail="Payment not found")

@app.post("/payments/{payment_id}/refund")
def refund_payment(payment_id: str, amount: float):
    if payment_id in payments_db:
        payments_db[payment_id]["status"] = "refunded"
        return {"refund_id": "rfnd_" + str(uuid.uuid4())[:8], "payment_id": payment_id, "amount": amount, "status": "processed"}
    raise HTTPException(status_code=404, detail="Payment not found")

