import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class Transaction {
    String transactionId;
    String userId;
    double amount;
    String currency;
    String status;

    public Transaction(String id, String userId, double amount, String currency, String status) {
        this.transactionId = id;
        this.userId = userId;
        this.amount = amount;
        this.currency = currency;
        this.status = status;
    }
}

class RazorpayGatewayService {
    private final Map<String, Transaction> idempotencyStore = new ConcurrentHashMap<>();
    private final Map<String, Transaction> transactionLedger = new ConcurrentHashMap<>();

    public synchronized Transaction processPayment(String idempotencyKey, String userId, double amount, String currency) {
        if (idempotencyStore.containsKey(idempotencyKey)) {
            System.out.println("[IDEMPOTENCY] Returning cached transaction for key: " + idempotencyKey);
            return idempotencyStore.get(idempotencyKey);
        }

        String txnId = "TXN_" + UUID.randomUUID().toString().substring(0, 8);
        Transaction txn = new Transaction(txnId, userId, amount, currency, "CAPTURED");

        idempotencyStore.put(idempotencyKey, txn);
        transactionLedger.put(txnId, txn);
        System.out.println("Payment successfully processed: " + txnId);
        return txn;
    }
}

