#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <shared_mutex>
#include <optional>
#include <chrono>

enum class PaymentStatus { CREATED, AUTHORIZED, CAPTURED, FAILED, REFUNDED };

struct PaymentRecord {
    std::string paymentId;
    std::string merchantId;
    double amount;
    std::string currency;
    PaymentStatus status;
    std::string idempotencyKey;
    std::string acquirerBank;
};

// 1. STRATEGY PATTERN: Smart Bank Acquirer Routing
class BankAcquirerRouter {
public:
    virtual ~BankAcquirerRouter() = default;
    virtual std::string selectBestAcquirer(const std::string& method, double amount) = 0;
};

class SmartRoutingEngine : public BankAcquirerRouter {
public:
    std::string selectBestAcquirer(const std::string& method, double amount) override {
        if (method == "UPI") return "HDFC_UPI_GATEWAY";
        if (amount > 50000.0) return "ICICI_CORPORATE_LEAP";
        return "AXIS_DIRECT_CARD_ROUTE";
    }
};

// 2. PRODUCTION THREAD-SAFE PAYMENT GATEWAY SERVICE
class RazorpayGateway {
private:
    std::unordered_map<std::string, PaymentRecord> idempotencyStore;
    std::unordered_map<std::string, PaymentRecord> transactionStore;
    std::shared_ptr<BankAcquirerRouter> router;

    mutable std::shared_mutex stateMutex;
    int txnCounter = 1000;

public:
    explicit RazorpayGateway(std::shared_ptr<BankAcquirerRouter> r) : router(std::move(r)) {}

    PaymentRecord createPayment(const std::string& idempotencyKey,
                                const std::string& merchantId,
                                double amount,
                                const std::string& currency,
                                const std::string& method) {
        // Step 1: Idempotency Check with Reader Lock
        {
            std::shared_lock<std::shared_mutex> readerLock(stateMutex);
            auto it = idempotencyStore.find(idempotencyKey);
            if (it != idempotencyStore.end()) {
                std::cout << "[IDEMPOTENT HIT] Request with key " << idempotencyKey 
                          << " already processed. Returning cached receipt.\n";
                return it->second;
            }
        }

        // Step 2: Acquire Exclusive Writer Lock
        std::unique_lock<std::shared_mutex> writerLock(stateMutex);

        // Double-check after lock
        auto it = idempotencyStore.find(idempotencyKey);
        if (it != idempotencyStore.end()) return it->second;

        std::string selectedBank = router->selectBestAcquirer(method, amount);
        std::string payId = "pay_" + std::to_string(++txnCounter);

        PaymentRecord record{
            payId,
            merchantId,
            amount,
            currency,
            PaymentStatus::AUTHORIZED,
            idempotencyKey,
            selectedBank
        };

        idempotencyStore[idempotencyKey] = record;
        transactionStore[payId] = record;

        std::cout << "[PAYMENT AUTHORIZED] ID: " << payId << " | Amount: " << amount 
                  << " " << currency << " routed to " << selectedBank << "\n";
        return record;
    }

    bool capturePayment(const std::string& paymentId, double amount) {
        std::unique_lock<std::shared_mutex> writerLock(stateMutex);
        auto it = transactionStore.find(paymentId);
        if (it == transactionStore.end()) return false;

        if (it->second.status == PaymentStatus::AUTHORIZED && it->second.amount == amount) {
            it->second.status = PaymentStatus::CAPTURED;
            std::cout << "[PAYMENT CAPTURED] ID: " << paymentId << " finalized successfully.\n";
            return true;
        }
        return false;
    }

    std::optional<PaymentRecord> getPayment(const std::string& paymentId) const {
        std::shared_lock<std::shared_mutex> readerLock(stateMutex);
        auto it = transactionStore.find(paymentId);
        if (it != transactionStore.end()) return it->second;
        return std::nullopt;
    }
};

int main() {
    auto smartRouter = std::make_shared<SmartRoutingEngine>();
    RazorpayGateway gateway(smartRouter);

    std::string key1 = "IDEM_TOKEN_9981";

    std::cout << "--- 1. Initiating Payment (Card Rs 1000) ---\n";
    auto p1 = gateway.createPayment(key1, "merchant_flipkart", 1000.0, "INR", "CARD");

    std::cout << "\n--- 2. Retrying Same Payment Request (Simulating Network Retry) ---\n";
    auto p2 = gateway.createPayment(key1, "merchant_flipkart", 1000.0, "INR", "CARD");

    std::cout << "\n--- 3. Capturing Authorized Payment ---\n";
    gateway.capturePayment(p1.paymentId, 1000.0);

    return 0;
}

