    private final Map<Long, Integer> inventoryStore = new ConcurrentHashMap<>();

    public void addProduct(Product p) {
        productCatalog.put(p.productId, p);
        inventoryStore.put(p.productId, p.inventory);
    }

    // Atomic Flash-Sale Stock Deduction
    public synchronized boolean purchaseProduct(long productId, int quantity) {
        int currentStock = inventoryStore.getOrDefault(productId, 0);
        if (currentStock >= quantity) {
            inventoryStore.put(productId, currentStock - quantity);
            System.out.println("Order successful for product: " + productId + ". Remaining stock: " + (currentStock - quantity));
            return true;
        }
        System.out.println("Order failed: Stock depleted for product: " + productId);
        return false;
    }
}

