    std::string status;
};

class AlibabaECommerceService {
private:
    std::unordered_map<int64_t, ProductRecord> products;
    std::unordered_map<int64_t, OrderRecord> orders;

    mutable std::shared_mutex catalogMutex;
    std::mutex orderMutex;
    int64_t orderCounter = 1000;

public:
    void createProduct(int64_t productId, int64_t sellerId, const std::string& name,
                       double price, int inventory, const std::string& category) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        products[productId] = ProductRecord{productId, sellerId, name, price, inventory, category};
        std::cout << "[Product Created] ID: " << productId << " | Name: " << name 
                  << " | Stock: " << inventory << "\n";
    }

    std::vector<ProductRecord> searchProducts(const std::string& category, double minPrice, double maxPrice) const {
        std::shared_lock<std::shared_mutex> lock(catalogMutex);
        std::vector<ProductRecord> results;
        for (const auto& [id, p] : products) {
            if ((category.empty() || p.category == category) &&
                (p.price >= minPrice && p.price <= maxPrice)) {
                results.push_back(p);
            }
        }
        return results;
    }

    // Thread-safe flash sale checkout with atomic inventory decrement
    std::optional<int64_t> purchaseProduct(int64_t userId, int64_t productId, int quantity) {
        std::unique_lock<std::shared_mutex> catLock(catalogMutex);
        auto it = products.find(productId);
        if (it == products.end()) {
            std::cout << "Purchase failed: Product not found.\n";
            return std::nullopt;
        }

        if (it->second.inventory < quantity) {
            std::cout << "Purchase failed: Insufficient stock for product: " << it->second.name 
                      << " (Requested: " << quantity << ", Available: " << it->second.inventory << ")\n";
            return std::nullopt;
        }

        // Atomic stock deduction
        it->second.inventory -= quantity;
        double total = it->second.price * quantity;

        std::lock_guard<std::mutex> oLock(orderMutex);
        int64_t newOrderId = ++orderCounter;
        orders[newOrderId] = OrderRecord{newOrderId, userId, productId, quantity, total, "PAID"};

        std::cout << "[ORDER CONFIRMED] Order ID: " << newOrderId << " | User: " << userId 
                  << " | Amount: $" << total << " | Remaining Stock: " << it->second.inventory << "\n";
        return newOrderId;
    }
};

