import java.util.concurrent.ConcurrentHashMap;

class Post {
    long postId;
    long authorId;
    String title;
    String content;
    boolean isPaidOnly;

    public Post(long postId, long authorId, String title, String content, boolean isPaidOnly) {
        this.postId = postId;
        this.authorId = authorId;
        this.title = title;
        this.content = content;
        this.isPaidOnly = isPaidOnly;
    }
}

class SubstackPublishingService {
    private final Map<Long, Post> postCatalog = new ConcurrentHashMap<>();
    private final Map<Long, Set<Long>> authorSubscribers = new ConcurrentHashMap<>();

    public void publishPost(Post post) {
        postCatalog.put(post.postId, post);
        System.out.println("Post published: " + post.title);
    }

    public void subscribe(long readerId, long authorId) {
        authorSubscribers.computeIfAbsent(authorId, k -> ConcurrentHashMap.newKeySet()).add(readerId);
    }

    public String readPost(long readerId, long postId) {
        Post post = postCatalog.get(postId);
        if (post == null) return "Not Found";
        if (post.isPaidOnly) {
            Set<Long> subs = authorSubscribers.getOrDefault(post.authorId, Collections.emptySet());
            if (!subs.contains(readerId)) {
                return post.content.substring(0, Math.min(post.content.length(), 100)) + "... [PAYWALL]";
            }
        }
        return post.content;
    }
}

