class SubstackPlatformService {
private:
    std::unordered_map<int64_t, SubstackPost> posts;
    std::unordered_map<int64_t, std::unordered_set<int64_t>> paidSubscribers; // authorId -> set of readerIds
    std::unordered_map<int64_t, std::vector<int64_t>> authorPostFeed;          // authorId -> list of postIds

    mutable std::shared_mutex postMutex;
    mutable std::shared_mutex subMutex;
    int64_t postCounter = 100;

public:
    int64_t publishPost(int64_t authorId, const std::string& title, const std::string& content, bool isPaidOnly) {
        std::unique_lock<std::shared_mutex> lock(postMutex);
        int64_t newPostId = ++postCounter;
        posts[newPostId] = SubstackPost{newPostId, authorId, title, content, isPaidOnly, 0};
        authorPostFeed[authorId].push_back(newPostId);
        std::cout << "[POST PUBLISHED] ID: " << newPostId << " | Title: '" << title << "'\n";
        return newPostId;
    }

    void subscribeToAuthor(int64_t readerId, int64_t authorId) {
        std::unique_lock<std::shared_mutex> lock(subMutex);
        paidSubscribers[authorId].insert(readerId);
        std::cout << "Reader " << readerId << " subscribed to Author " << authorId << "\n";
    }

    std::string readPost(int64_t readerId, int64_t postId) const {
        std::shared_lock<std::shared_mutex> pLock(postMutex);
        auto it = posts.find(postId);
        if (it == posts.end()) return "Error 404: Post Not Found";

        const auto& post = it->second;
        if (post.isPaidOnly) {
            std::shared_lock<std::shared_mutex> sLock(subMutex);
            auto subIt = paidSubscribers.find(post.authorId);
            if (subIt == paidSubscribers.end() || subIt->second.find(readerId) == subIt->second.end()) {
                return post.content.substr(0, 50) + "... [LOCKED: Subscribe for full article]";
            }
        }
        return post.content;
    }

    void likePost(int64_t postId) {
        std::unique_lock<std::shared_mutex> lock(postMutex);
        auto it = posts.find(postId);
        if (it != posts.end()) {
            it->second.likesCount++;
            std::cout << "Post " << postId << " liked! Total likes: " << it->second.likesCount << "\n";
        }
    }
};

int main() {
    SubstackPlatformService substack;

    int64_t authorAlice = 1;
    int64_t readerBob = 201;
    int64_t readerCharlie = 202;

    // 1. Author publishes a free post and a paid post
    int64_t freePost = substack.publishPost(authorAlice, "Welcome to my Blog", "This is a free introductory post for everyone.", false);
    int64_t paidPost = substack.publishPost(authorAlice, "Deep Market Analysis", "Exclusive paid alpha: Buy stocks X, Y, Z and hold long-term.", true);

    // 2. Reader Charlie purchases a subscription
    substack.subscribeToAuthor(readerCharlie, authorAlice);

    // 3. Reader Bob (free) reads both posts
    std::cout << "\n--- Bob reads Free Post ---\n" << substack.readPost(readerBob, freePost) << "\n";
    std::cout << "\n--- Bob reads Paid Post (Paywalled) ---\n" << substack.readPost(readerBob, paidPost) << "\n";

