import java.util.concurrent.ConcurrentHashMap;

class ChatMessage {
    long messageId;
    long senderId;
    long receiverId;
    String content;
    boolean delivered;

    public ChatMessage(long messageId, long senderId, long receiverId, String content) {
        this.messageId = messageId;
        this.senderId = senderId;
        this.receiverId = receiverId;
        this.content = content;
        this.delivered = false;
    }
}

class InstantMessengerService {
    private final Map<Long, String> activeUserSockets = new ConcurrentHashMap<>();
    private final List<ChatMessage> messageStore = Collections.synchronizedList(new ArrayList<>());

    public void connectUser(long userId, String socketGateway) {
        activeUserSockets.put(userId, socketGateway);
    }

    public void disconnectUser(long userId) {
        activeUserSockets.remove(userId);
    }

    public synchronized ChatMessage routeMessage(long senderId, long receiverId, String text) {
        long msgId = System.currentTimeMillis();
        ChatMessage msg = new ChatMessage(msgId, senderId, receiverId, text);

        if (activeUserSockets.containsKey(receiverId)) {
            msg.delivered = true;
            System.out.println("Dispatched directly to live socket: " + activeUserSockets.get(receiverId));
        } else {
            System.out.println("Recipient offline. Triggering Apple/Google Push Notification.");
        }
        messageStore.add(msg);
        return msg;
    }
}

