#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>
#include <chrono>

struct InstantMessage {
    int64_t messageId;
    int64_t senderId;
    int64_t receiverId;
    std::string content;
    bool isDelivered;
    bool isRead;
    int64_t timestamp;
};

class InstantMessengerEngine {
private:
    std::unordered_map<int64_t, std::string> userSessions; // userId -> gatewayHost
    std::unordered_map<int64_t, std::vector<InstantMessage>> userInboxes;

    mutable std::shared_mutex sessionMutex;
    std::mutex inboxMutex;
    int64_t messageCounter = 1000;

public:
    void registerSession(int64_t userId, const std::string& gatewayHost) {
        std::unique_lock<std::shared_mutex> lock(sessionMutex);
        userSessions[userId] = gatewayHost;
        std::cout << "[Presence Online] User " << userId << " connected on " << gatewayHost << "\n";
    }

    void removeSession(int64_t userId) {
        std::unique_lock<std::shared_mutex> lock(sessionMutex);
        userSessions.erase(userId);
        std::cout << "[Presence Offline] User " << userId << " disconnected.\n";
    }

    InstantMessage sendMessage(int64_t senderId, int64_t receiverId, const std::string& content) {
        bool isOnline = false;
        std::string targetGateway;
        {
            std::shared_lock<std::shared_mutex> sLock(sessionMutex);
            auto it = userSessions.find(receiverId);
            if (it != userSessions.end()) {
                isOnline = true;
                targetGateway = it->second;
            }
        }

        std::lock_guard<std::mutex> iLock(inboxMutex);
        int64_t msgId = ++messageCounter;
        auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        InstantMessage msg{msgId, senderId, receiverId, content, isOnline, false, now};
        userInboxes[receiverId].push_back(msg);
        userInboxes[senderId].push_back(msg);

        if (isOnline) {
            std::cout << "[ROUTED VIA WEBSOCKET] Msg ID: " << msgId << " -> " << targetGateway << " for User " << receiverId << "\n";
        } else {
            std::cout << "[OFFLINE QUEUED] Msg ID: " << msgId << " -> Pushed to APNs/FCM for User " << receiverId << "\n";
        }
        return msg;
    }

    std::vector<InstantMessage> pullInbox(int64_t userId) {
        std::lock_guard<std::mutex> lock(inboxMutex);
        return userInboxes[userId];
    }
};

int main() {
    InstantMessengerEngine engine;

    int64_t alice = 101;
    int64_t bob = 102;
    int64_t charlie = 103;

    // 1. Alice and Bob connect over WebSockets
    engine.registerSession(alice, "gateway-us-east-1a");
    engine.registerSession(bob, "gateway-us-east-1b");

    // 2. Alice sends message to online Bob
    std::cout << "\n--- 1. Alice sends message to online Bob ---\n";
    engine.sendMessage(alice, bob, "Hey Bob, are we ready for the release?");

    // 3. Alice sends message to offline Charlie
    std::cout << "\n--- 2. Alice sends message to offline Charlie ---\n";
    engine.sendMessage(alice, charlie, "Hey Charlie, check your email when you wake up!");

    // 4. Charlie comes online and syncs inbox
    std::cout << "\n--- 3. Charlie comes online and pulls offline queue ---\n";
    engine.registerSession(charlie, "gateway-eu-west-1a");
    auto charlieMsgs = engine.pullInbox(charlie);
    for (const auto& m : charlieMsgs) {
        std::cout << "Received Sync Msg: " << m.content << " (Delivered: " << m.isDelivered << ")\n";
    }

    return 0;
}

