import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class HNPost {
    long postId;
    String title;
    String url;
    long authorId;
    int points;
    long timestampMillis;

    public HNPost(long postId, String title, String url, long authorId) {
        this.postId = postId;
        this.title = title;
        this.url = url;
        this.authorId = authorId;
        this.points = 1;
        this.timestampMillis = System.currentTimeMillis();
    }

    public double calculateScore(double gravity) {
        double hours = (System.currentTimeMillis() - this.timestampMillis) / 3600000.0;
        return (this.points - 1) / Math.pow(hours + 2.0, gravity);
    }
}

class HackerNewsService {
    private final Map<Long, HNPost> postMap = new ConcurrentHashMap<>();
    private final Set<String> voteLedger = ConcurrentHashMap.newKeySet();

    public void submitPost(HNPost post) {
        postMap.put(post.postId, post);
    }

    public synchronized boolean upvote(long userId, long postId) {
        String key = userId + ":" + postId;
        if (voteLedger.contains(key)) return false;
        HNPost post = postMap.get(postId);
        if (post != null) {
            post.points++;
            voteLedger.add(key);
            return true;
        }
        return false;
    }

    public List<HNPost> getTopStories(int limit) {
        List<HNPost> list = new ArrayList<>(postMap.values());
        list.sort((a, b) -> Double.compare(b.calculateScore(1.8), a.calculateScore(1.8)));
        return list.subList(0, Math.min(list.size(), limit));
    }
}

