struct PostItem {
    int64_t postId;
    std::string title;
    std::string url;
    int64_t authorId;
    int upvotes = 1;
    std::chrono::system_clock::time_point createdAt;

    double getRankingScore(double gravity = 1.8) const {
        auto now = std::chrono::system_clock::now();
        double hoursAge = std::chrono::duration<double, std::ratio<3600>>(now - createdAt).count();
        return (upvotes - 1.0) / std::pow(hoursAge + 2.0, gravity);
    }
};

struct CommentNode {
    int64_t commentId;
    int64_t postId;
    int64_t parentCommentId; // 0 for root
    int64_t authorId;
    std::string content;
    std::string materializedPath;
};

class HackerNewsEngine {
private:
    std::unordered_map<int64_t, PostItem> posts;
    std::unordered_map<int64_t, std::vector<CommentNode>> postComments; // postId -> comments
    std::unordered_set<std::string> voteRecords; // "userId:postId"

    mutable std::shared_mutex postMutex;
    std::mutex voteMutex;
    std::mutex commentMutex;
    int64_t postCounter = 100;
    int64_t commentCounter = 500;

public:
    int64_t submitPost(int64_t authorId, const std::string& title, const std::string& url) {
        std::unique_lock<std::shared_mutex> lock(postMutex);
        int64_t newId = ++postCounter;
        posts[newId] = PostItem{newId, title, url, authorId, 1, std::chrono::system_clock::now()};
        std::cout << "[POST SUBMITTED] ID: " << newId << " | '" << title << "'\n";
        return newId;
    }

    bool upvotePost(int64_t userId, int64_t postId) {
        std::string voteKey = std::to_string(userId) + ":" + std::to_string(postId);
        {
            std::lock_guard<std::mutex> vLock(voteMutex);
            if (voteRecords.find(voteKey) != voteRecords.end()) {
                std::cout << "Vote rejected: User " << userId << " already voted on Post " << postId << "\n";
                return false;
            }
            voteRecords.insert(voteKey);
        }

        std::unique_lock<std::shared_mutex> pLock(postMutex);
        auto it = posts.find(postId);
        if (it != posts.end()) {
            it->second.upvotes++;
            std::cout << "[VOTE APPLIED] Post " << postId << " now has " << it->second.upvotes << " points.\n";
            return true;
        }
        return false;
    }

    std::vector<PostItem> getRankedFrontPage(size_t limit = 30) const {
        std::shared_lock<std::shared_mutex> lock(postMutex);
        std::vector<PostItem> result;
        for (const auto& [id, p] : posts) result.push_back(p);

        std::sort(result.begin(), result.end(), [](const PostItem& a, const PostItem& b) {
            return a.getRankingScore() > b.getRankingScore();
        });

        if (result.size() > limit) result.resize(limit);
        return result;
    }

    int64_t addComment(int64_t postId, int64_t authorId, int64_t parentId, const std::string& content) {
        std::lock_guard<std::mutex> lock(commentMutex);
        int64_t newId = ++commentCounter;
        std::string path = (parentId == 0) ? std::to_string(newId) : std::to_string(parentId) + "." + std::to_string(newId);
        postComments[postId].push_back(CommentNode{newId, postId, parentId, authorId, content, path});
        std::cout << "[COMMENT ADDED] ID: " << newId << " on Post " << postId << " (Path: " << path << ")\n";
        return newId;
    }
};

int main() {
    HackerNewsEngine engine;

    // 1. Submit two posts
    int64_t p1 = engine.submitPost(1, "Why C++20 Ranges Change Everything", "https://isocpp.org/ranges");
    int64_t p2 = engine.submitPost(2, "Show HN: Fast Distributed In-Memory Cache", "https://github.com/fastcache");

    // 2. Users upvote
    engine.upvotePost(101, p2);
    engine.upvotePost(102, p2);
    engine.upvotePost(103, p2); // p2 has 4 points total

    // 3. Prevent duplicate voting
