    // 4. Add hierarchical threaded comments
    int64_t c1 = engine.addComment(p2, 101, 0, "Impressive benchmarks! Does it support Redis protocol?");
    engine.addComment(p2, 2, c1, "Yes, fully wire-compatible with RESP.");

    // 5. Inspect ranked front page
    std::cout << "\n--- Hacker News Front Page (Ranked via Gravity Algorithm) ---\n";
    auto frontpage = engine.getRankedFrontPage();
