import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

enum PrivacyLevel { PUBLIC, FRIENDS, ONLY_ME }

class TimelinePost {
    String postId;
    String userId;
    String content;
    PrivacyLevel privacy;
    boolean isPinned;
    long timestampMillis;

    public TimelinePost(String postId, String userId, String content, PrivacyLevel privacy, boolean isPinned) {
        this.postId = postId;
        this.userId = userId;
        this.content = content;
        this.privacy = privacy;
        this.isPinned = isPinned;
        this.timestampMillis = System.currentTimeMillis();
    }
}

class FacebookTimelineService {
    private final Map<String, List<TimelinePost>> userTimelines = new ConcurrentHashMap<>();
    private final Map<String, Set<String>> friendGraph = new ConcurrentHashMap<>();

    public void addPost(TimelinePost post) {
        userTimelines.computeIfAbsent(post.userId, k -> Collections.synchronizedList(new ArrayList<>())).add(post);
    }

    public void addFriendship(String u1, String u2) {
        friendGraph.computeIfAbsent(u1, k -> ConcurrentHashMap.newKeySet()).add(u2);
        friendGraph.computeIfAbsent(u2, k -> ConcurrentHashMap.newKeySet()).add(u1);
    }

    public List<TimelinePost> getTimeline(String profileOwnerId, String viewerId) {
        List<TimelinePost> allPosts = userTimelines.getOrDefault(profileOwnerId, Collections.emptyList());
        boolean isOwner = profileOwnerId.equals(viewerId);
        boolean isFriend = friendGraph.getOrDefault(profileOwnerId, Collections.emptySet()).contains(viewerId);

        return allPosts.stream()
            .filter(p -> isOwner || p.privacy == PrivacyLevel.PUBLIC || (p.privacy == PrivacyLevel.FRIENDS && isFriend))
            .sorted(Comparator.comparing((TimelinePost p) -> !p.isPinned)
                .thenComparing((TimelinePost p) -> -p.timestampMillis))
            .collect(Collectors.toList());
    }
}

