#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <algorithm>
#include <chrono>

enum class PrivacyLevel { PUBLIC, FRIENDS, ONLY_ME };

struct TimelinePost {
    int64_t postId;
    int64_t userId;
    std::string content;
    std::string mediaUrl;
    PrivacyLevel privacy;
    bool isPinned;
    std::chrono::system_clock::time_point timestamp;
};

class FacebookTimelineEngine {
private:
    std::unordered_map<int64_t, std::vector<TimelinePost>> timelineLedger; // userId -> posts
    std::unordered_map<int64_t, std::unordered_set<int64_t>> friendships;  // userId -> friend set

    mutable std::shared_mutex ledgerMutex;
    mutable std::shared_mutex friendMutex;
    int64_t postCounter = 1000;

public:
    void addFriendship(int64_t u1, int64_t u2) {
        std::unique_lock<std::shared_mutex> lock(friendMutex);
        friendships[u1].insert(u2);
        friendships[u2].insert(u1);
    }

    int64_t createPost(int64_t userId, const std::string& content, const std::string& mediaUrl,
                       PrivacyLevel privacy, bool isPinned = false) {
        std::unique_lock<std::shared_mutex> lock(ledgerMutex);
        int64_t pId = ++postCounter;
        timelineLedger[userId].push_back(TimelinePost{
            pId, userId, content, mediaUrl, privacy, isPinned, std::chrono::system_clock::now()
        });
        std::cout << "[POST CREATED] ID: " << pId << " by User: " << userId 
                  << " (Pinned: " << (isPinned ? "YES" : "NO") << ")\n";
        return pId;
    }

    std::vector<TimelinePost> getTimeline(int64_t targetUserId, int64_t viewerUserId) const {
        bool isOwner = (targetUserId == viewerUserId);
        bool isFriend = false;
        {
            std::shared_lock<std::shared_mutex> fLock(friendMutex);
            auto it = friendships.find(targetUserId);
            if (it != friendships.end() && it->second.find(viewerUserId) != it->second.end()) {
                isFriend = true;
            }
        }

        std::shared_lock<std::shared_mutex> pLock(ledgerMutex);
        std::vector<TimelinePost> filtered;
        auto it = timelineLedger.find(targetUserId);
        if (it == timelineLedger.end()) return filtered;

        for (const auto& post : it->second) {
            if (isOwner) {
                filtered.push_back(post);
            } else if (post.privacy == PrivacyLevel.PUBLIC) {
                filtered.push_back(post);
            } else if (post.privacy == PrivacyLevel.FRIENDS && isFriend) {
                filtered.push_back(post);
            }
        }

        // Pinned posts first, then reverse chronological
        std::sort(filtered.begin(), filtered.end(), [](const TimelinePost& a, const TimelinePost& b) {
            if (a.isPinned != b.isPinned) return a.isPinned > b.isPinned;
            return a.timestamp > b.timestamp;
        });

        return filtered;
    }
};

int main() {
    FacebookTimelineEngine engine;

    int64_t alice = 101;
    int64_t bob = 102;     // Friend of Alice
    int64_t charlie = 103; // Stranger

    // 1. Establish friendship between Alice and Bob
    engine.addFriendship(alice, bob);

    // 2. Alice creates multiple posts with different privacy settings
    engine.createPost(alice, "Graduated from Stanford University!", "grad.jpg", PrivacyLevel::PUBLIC, true); // Pinned
    engine.createPost(alice, "Weekend beach trip with close friends.", "beach.jpg", PrivacyLevel::FRIENDS, false);
    engine.createPost(alice, "Private journal thoughts.", "", PrivacyLevel::ONLY_ME, false);

    // 3. Alice views her own timeline (should see all 3 posts)
    std::cout << "\n--- 1. Alice viewing her own Timeline (3 posts) ---\n";
    auto aliceView = engine.getTimeline(alice, alice);
    for (const auto& p : aliceView) {
        std::cout << "[Post " << p.postId << "] " << p.content << " (Pinned: " << p.isPinned << ")\n";
    }

    // 4. Bob (Friend) views Alice's timeline (should see Public + Friends Only = 2 posts)
    std::cout << "\n--- 2. Bob (Friend) viewing Alice's Timeline (2 posts) ---\n";
    auto bobView = engine.getTimeline(alice, bob);
    for (const auto& p : bobView) {
        std::cout << "[Post " << p.postId << "] " << p.content << " (Pinned: " << p.isPinned << ")\n";
    }

    // 5. Charlie (Stranger) views Alice's timeline (should see only Public = 1 post)
    std::cout << "\n--- 3. Charlie (Stranger) viewing Alice's Timeline (1 post) ---\n";
    auto charlieView = engine.getTimeline(alice, charlie);
    for (const auto& p : charlieView) {
        std::cout << "[Post " << p.postId << "] " << p.content << " (Pinned: " << p.isPinned << ")\n";
    }

    return 0;
}

