enum ActionType { FOLD, CHECK, CALL, BET, RAISE }

class PokerPlayer {
    long userId;
    String username;
    double chips;
    List<String> holeCards;
    boolean isFolded;

    public PokerPlayer(long id, String name, double chips) {
        this.userId = id;
        this.username = name;
        this.chips = chips;
        this.holeCards = new ArrayList<>();
        this.isFolded = false;
    }
}

class PokerTable {
    String tableId;
    Map<Long, PokerPlayer> players = new ConcurrentHashMap<>();
    double pot = 0.0;
    double currentBet = 0.0;
    List<String> communityCards = new ArrayList<>();

    public PokerTable(String tableId) {
        this.tableId = tableId;
    }

    public synchronized boolean handleAction(long userId, ActionType action, double amount) {
        PokerPlayer p = players.get(userId);
        if (p == null || p.isFolded) return false;

        switch (action) {
            case FOLD:
                p.isFolded = true;
                System.out.println(p.username + " FOLDED");
                break;
            case BET:
            case RAISE:
                if (p.chips < amount) return false;
                p.chips -= amount;
                pot += amount;
                currentBet = amount;
                System.out.println(p.username + " BET " + amount + " | Pot: " + pot);
                break;
            case CALL:
                double toCall = currentBet;
                if (p.chips < toCall) return false;
                p.chips -= toCall;
                pot += toCall;
                System.out.println(p.username + " CALLED " + toCall);
                break;
            default:
                break;
        }
        return true;
    }
}

