#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <shared_mutex>
#include <random>
#include <algorithm>

enum class PokerAction { FOLD, CHECK, CALL, BET, RAISE };
enum class GameRound { PRE_FLOP, FLOP, TURN, RIVER, SHOWDOWN };

struct PlayerState {
    int64_t userId;
    std::string name;
    double chipStack;
    std::vector<std::string> holeCards;
    bool hasFolded = false;
    double currentRoundBet = 0.0;
};

class TexasHoldemTable {
private:
    std::string tableId;
    std::unordered_map<int64_t, PlayerState> players;
    std::vector<std::string> deck;
    std::vector<std::string> communityCards;
    double pot = 0.0;
    double highestBet = 0.0;
    GameRound currentRound = GameRound::PRE_FLOP;

    mutable std::mutex tableMutex;

    void initDeck() {
        deck.clear();
        std::vector<std::string> suits = {"S", "H", "D", "C"};
        std::vector<std::string> ranks = {"2","3","4","5","6","7","8","9","T","J","Q","K","A"};
        for (const auto& s : suits) {
            for (const auto& r : ranks) {
                deck.push_back(r + s);
            }
        }
        // Cryptographically secure random device shuffle (Fisher-Yates)
        std::random_device rd;
        std::mt19937 g(rd());
        std::shuffle(deck.begin(), deck.end(), g);
    }

public:
    explicit TexasHoldemTable(std::string id) : tableId(std::move(id)) {
        initDeck();
    }

    bool addPlayer(int64_t userId, const std::string& name, double buyIn) {
        std::lock_guard<std::mutex> lock(tableMutex);
        if (players.size() >= 6) return false;
        players[userId] = PlayerState{userId, name, buyIn, {}, false, 0.0};
        std::cout << "Player " << name << " seated with $" << buyIn << "\n";
        return true;
    }

    void dealHoleCards() {
        std::lock_guard<std::mutex> lock(tableMutex);
        for (auto& [id, player] : players) {
            player.holeCards.clear();
            player.holeCards.push_back(deck.back()); deck.pop_back();
            player.holeCards.push_back(deck.back()); deck.pop_back();
            std::cout << "Dealt private cards to " << player.name << "\n";
        }
    }

    bool executeAction(int64_t userId, PokerAction action, double amount = 0.0) {
        std::lock_guard<std::mutex> lock(tableMutex);
        auto it = players.find(userId);
        if (it == players.end() || it->second.hasFolded) return false;

        auto& player = it->second;

        if (action == PokerAction::FOLD) {
            player.hasFolded = true;
            std::cout << "[ACTION] " << player.name << " FOLDED.\n";
            return true;
        }

        if (action == PokerAction::BET || action == PokerAction::RAISE) {
            if (player.chipStack < amount) return false;
            player.chipStack -= amount;
            player.currentRoundBet += amount;
            pot += amount;
            highestBet = player.currentRoundBet;
            std::cout << "[ACTION] " << player.name << " BET/RAISED $" << amount 
                      << " \vert{} Pot: $" << pot << "\n";
            return true;
        }

        if (action == PokerAction::CALL) {
            double callAmount = highestBet - player.currentRoundBet;
            if (player.chipStack < callAmount) return false;
            player.chipStack -= callAmount;
            player.currentRoundBet += callAmount;
            pot += callAmount;
            std::cout << "[ACTION] " << player.name << " CALLED $" << callAmount 
                      << " \vert{} Pot: $" << pot << "\n";
            return true;
        }
        return false;
    }

    // Simulates Flop Deal (3 community cards)
    void dealFlop() {
        std::lock_guard<std::mutex> lock(tableMutex);
        deck.pop_back(); // Burn card
        for (int i = 0; i < 3; ++i) {
            communityCards.push_back(deck.back());
            deck.pop_back();
        }
        currentRound = GameRound::FLOP;
        std::cout << "[BOARD FLOP] " << communityCards[0] << " " 
                  << communityCards[1] << " " << communityCards[2] << "\n";
    }

    double getPot() const {
        std::lock_guard<std::mutex> lock(tableMutex);
        return pot;
    }
};

int main() {
    TexasHoldemTable table("TABLE_VVIP_01");

    table.addPlayer(101, "Phil_Ivey", 500.0);
    table.addPlayer(102, "Daniel_Negreanu", 500.0);

    std::cout << "\n--- Round 1: Pre-Flop Dealing ---\n";
    table.dealHoleCards();

    std::cout << "\n--- Round 2: Pre-Flop Betting ---\n";
    table.executeAction(101, PokerAction::BET, 20.0);   // Phil bets $20
    table.executeAction(102, PokerAction::CALL, 20.0);  // Daniel calls $20

    std::cout << "\n--- Round 3: Flop Community Cards ---\n";
    table.dealFlop();

    std::cout << "\n--- Round 4: Post-Flop Action ---\n";
    table.executeAction(101, PokerAction::BET, 50.0);
    table.executeAction(102, PokerAction::FOLD);

    std::cout << "Final Table Pot: $" << table.getPot() << " awarded to winner.\n";
    return 0;
}

