class Package:
    def __init__(self, pkg_id, user_id, size):
        self.id = pkg_id
        self.user_id = user_id
        self.size = size
        self.locker_id = None
        self.pickup_code = None
        self.status = "CREATED" # CREATED, IN_LOCKER, PICKED_UP, EXPIRED

# Seed dummy location and lockers
loc_id = "loc_1"
locations[loc_id] = {"name": "Downtown Hub", "total": 3}
lockers["lkr_1"] = Locker("lkr_1", loc_id, "SMALL")
lockers["lkr_2"] = Locker("lkr_2", loc_id, "MEDIUM")
lockers["lkr_3"] = Locker("lkr_3", loc_id, "LARGE")

@app.route('/api/packages/create', methods=['POST'])
def create_package():
    data = request.get_json() or {}
    pkg_id = "PKG_" + str(uuid.uuid4())[:8]
    pkg = Package(pkg_id, data.get('user_id'), data.get('size', 'SMALL'))
    packages[pkg_id] = pkg
    return jsonify({'package_id': pkg_id, 'status': pkg.status}), 201

@app.route('/api/driver/deposit', methods=['POST'])
def driver_deposit():
    data = request.get_json() or {}
    pkg_id = data.get('package_id')
    loc_id = data.get('location_id')

    pkg = packages.get(pkg_id)
    if not pkg:
        return jsonify({'error': 'Package not found'}), 404

    # Find best fitting available locker
    available_locker = None
    for lkr in lockers.values():
        if lkr.location_id == loc_id and not lkr.occupied and lkr.size == pkg.size:
            available_locker = lkr
            break

    if not available_locker:
        return jsonify({'error': 'No suitable locker slots available'}), 400

    # Atomic assignment
    available_locker.occupied = True
