import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

enum LockerSize { SMALL, MEDIUM, LARGE, XLARGE }

class LockerCompartment {
    String lockerId;
    String locationId;
    LockerSize size;
    boolean isOccupied;
    String assignedPackageId;

    public LockerCompartment(String id, String locId, LockerSize size) {
        this.lockerId = id;
        this.locationId = locId;
        this.size = size;
        this.isOccupied = false;
    }
}

class AmazonLockerService {
    private final Map<String, LockerCompartment> lockerInventory = new ConcurrentHashMap<>();
    private final Map<String, String> packageToCodeMap = new ConcurrentHashMap<>();

    public synchronized LockerCompartment assignAndDeposit(String packageId, String locationId, LockerSize requiredSize) {
        for (LockerCompartment lkr : lockerInventory.values()) {
            if (lkr.locationId.equals(locationId) && !lkr.isOccupied && lkr.size == requiredSize) {
                lkr.isOccupied = true;
                lkr.assignedPackageId = packageId;
                String code = String.valueOf(100000 + new Random().nextInt(900000));
                packageToCodeMap.put(packageId, code);
                System.out.println("Package " + packageId + " deposited into Locker: " + lkr.lockerId + " | OTP: " + code);
                return lkr;
            }
        }
        return null;
    }

    public synchronized boolean pickupWithCode(String packageId, String enteredCode) {
        String actualCode = packageToCodeMap.get(packageId);
        if (actualCode != null && actualCode.equals(enteredCode)) {
            for (LockerCompartment lkr : lockerInventory.values()) {
                if (packageId.equals(lkr.assignedPackageId)) {
                    lkr.isOccupied = false;
                    lkr.assignedPackageId = null;
                    packageToCodeMap.remove(packageId);
                    System.out.println("Locker " + lkr.lockerId + " released. Package collected!");
                    return true;
                }
            }
        }
        return false;
    }
}

