#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>
#include <chrono>
#include <random>

enum class SlotSize { SMALL, MEDIUM, LARGE, XLARGE };
enum class PackageState { IN_TRANSIT, DELIVERED_TO_LOCKER, PICKED_UP, EXPIRED };

struct LockerSlot {
    std::string slotId;
    std::string locationId;
    SlotSize size;
    bool isOccupied = false;
    std::string packageId = "";
};

struct LockerPackage {
    std::string packageId;
    std::string userId;
    SlotSize requiredSize;
    std::string assignedSlotId;
    std::string pickupOtp;
    PackageState state;
    std::chrono::system_clock::time_point expiryTime;
};

class AmazonLockerEngine {
private:
    std::unordered_map<std::string, LockerSlot> slots;             // slotId -> LockerSlot
    std::unordered_map<std::string, LockerPackage> packages;       // packageId -> LockerPackage
    std::unordered_map<std::string, std::string> otpToPackageMap;  // pickupOtp -> packageId

    mutable std::shared_mutex engineMutex;

    std::string generateSecureOtp() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dist(100000, 999999);
        return std::to_string(dist(gen));
    }

public:
    void registerLockerSlot(const std::string& slotId, const std::string& locationId, SlotSize size) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        slots[slotId] = LockerSlot{slotId, locationId, size, false, ""};
    }

    void createPackageOrder(const std::string& packageId, const std::string& userId, SlotSize size) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        packages[packageId] = LockerPackage{packageId, userId, size, "", "", PackageState::IN_TRANSIT, {}};
    }

    // Driver deposits package into physical locker kiosk
    std::optional<std::string> driverDepositPackage(const std::string& packageId, const std::string& locationId) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        auto pIt = packages.find(packageId);
        if (pIt == packages.end() || pIt->second.state != PackageState::IN_TRANSIT) {
            std::cout << "Deposit rejected: Invalid package ID or state.\n";
            return std::nullopt;
        }

        // Find optimal available slot (Size matching)
        std::string selectedSlotId = "";
        for (auto& [id, slot] : slots) {
            if (slot.locationId == locationId && !slot.isOccupied && slot.size == pIt->second.requiredSize) {
                selectedSlotId = id;
                break;
            }
        }

        if (selectedSlotId.empty()) {
            std::cout << "Deposit failed: No suitable locker compartments available at location: " << locationId << "\n";
            return std::nullopt;
        }

        // Commit deposit state
        auto otp = generateSecureOtp();
        auto now = std::chrono::system_clock::now();
        auto expiry = now + std::chrono::hours(72); // 3-day pickup window

        slots[selectedSlotId].isOccupied = true;
        slots[selectedSlotId].packageId = packageId;

        pIt->second.assignedSlotId = selectedSlotId;
        pIt->second.pickupOtp = otp;
        pIt->second.state = PackageState::DELIVERED_TO_LOCKER;
        pIt->second.expiryTime = expiry;

        otpToPackageMap[otp] = packageId;

        std::cout << "[DRIVER ACTION] Package " << packageId << " deposited in Slot: " << selectedSlotId 
                  << " | OTP generated: " << otp << " (Expires in 72h)\n";
        return otp;
    }

    // Customer enters 6-digit OTP on Kiosk Screen
    bool customerPickupPackage(const std::string& enteredOtp) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        auto otpIt = otpToPackageMap.find(enteredOtp);
        if (otpIt == otpToPackageMap.end()) {
            std::cout << "Pickup rejected: Invalid OTP entered.\n";
            return false;
        }

        std::string pkgId = otpIt->second;
        auto& pkg = packages[pkgId];

        if (std::chrono::system_clock::now() > pkg.expiryTime) {
            std::cout << "Pickup rejected: 72-hour collection window expired. Package flagged for return.\n";
            pkg.state = PackageState::EXPIRED;
            return false;
        }

        // Release locker slot
        std::string slotId = pkg.assignedSlotId;
        slots[slotId].isOccupied = false;
        slots[slotId].packageId = "";

        pkg.state = PackageState::PICKED_UP;
        otpToPackageMap.erase(otpIt);

        std::cout << "[DOOR UNLOCKED] Solenoid released for Slot " << slotId 
                  << ". Customer collected Package " << pkgId << "!\n";
        return true;
    }
};

int main() {
    AmazonLockerEngine lockerSystem;

    std::string locDowntown = "LOC_DOWNTOWN_01";

    // 1. Setup Kiosk Hardware Slots
    lockerSystem.registerLockerSlot("SLOT_101", locDowntown, SlotSize::SMALL);
    lockerSystem.registerLockerSlot("SLOT_102", locDowntown, SlotSize::MEDIUM);
    lockerSystem.registerLockerSlot("SLOT_103", locDowntown, SlotSize::LARGE);

    // 2. Customer places order
    lockerSystem.createPackageOrder("PKG_AMZ_889", "user_rahul", SlotSize::MEDIUM);

    // 3. Driver arrives at kiosk and deposits package
    std::cout << "--- 1. Driver Arrives at Locker Kiosk ---\n";
    auto generatedOtp = lockerSystem.driverDepositPackage("PKG_AMZ_889", locDowntown);

    // 4. Customer picks up using OTP
    if (generatedOtp) {
        std::cout << "\n--- 2. Customer Arrives with OTP ---\n";
        lockerSystem.customerPickupPackage(*generatedOtp);
    }

    // 5. Attempt duplicate pickup with already used OTP
    std::cout << "\n--- 3. Attempt Duplicate Pickup ---\n";
    lockerSystem.customerPickupPackage(generatedOtp.value_or("000000"));

    return 0;
}

