import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class FileChunk {
    String chunkHash;
    byte[] data;

    public FileChunk(String hash, byte[] data) {
        this.chunkHash = hash;
        this.data = data;
    }
}

class DropboxService {
    // In-memory Global Chunk Store (Deduplicated)
    private final Map<String, FileChunk> globalChunkStorage = new ConcurrentHashMap<>();
    // File Manifest Map: FileId -> List of ChunkHashes
    private final Map<String, List<String>> fileManifests = new ConcurrentHashMap<>();
    private final Map<String, Long> fileVersions = new ConcurrentHashMap<>();

    public synchronized void uploadChunk(String hash, byte[] data) {
        if (!globalChunkStorage.containsKey(hash)) {
            globalChunkStorage.put(hash, new FileChunk(hash, data));
            System.out.println("[BlockServer] Stored new unique chunk: " + hash.substring(0, 8));
        } else {
            System.out.println("[Deduplication] Chunk already exists in S3: " + hash.substring(0, 8));
        }
    }

    public synchronized boolean commitManifest(String fileId, long baseVersion, List<String> hashes) {
        long currentVer = fileVersions.getOrDefault(fileId, 0L);
        if (baseVersion != currentVer) {
            System.out.println("[Conflict] Commit rejected! Stale base version for file: " + fileId);
            return false;
        }

        fileManifests.put(fileId, new ArrayList<>(hashes));
        fileVersions.put(fileId, currentVer + 1);
        System.out.println("[MetadataServer] Committed version " + (currentVer + 1) + " for " + fileId);
        return true;
    }

    public List<String> getManifest(String fileId) {
        return fileManifests.getOrDefault(fileId, Collections.emptyList());
    }
}

