#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <sstream>
#include <iomanip>
#include <optional>

// Represents an immutable 4MB chunk block
struct StoredChunk {
    std::string chunkHash;
    size_t sizeBytes;
    int referenceCount = 0;
};

struct FileVersionManifest {
    int64_t versionNumber;
    std::vector<std::string> orderedChunkHashes;
    std::string deviceId;
    int64_t timestamp;
};

class DropboxEngine {
private:
    // Global Deduplicated Block Repository: Hash -> Chunk Metadata
    std::unordered_map<std::string, StoredChunk> chunkStore;
    // File Metadata: FileId -> Revisions list
    std::unordered_map<std::string, std::vector<FileVersionManifest>> fileRevisions;

    mutable std::shared_mutex chunkMutex;
    mutable std::shared_mutex manifestMutex;

public:
    // 1. Block Server: Upload chunk with global deduplication check
    bool uploadBlockChunk(const std::string& chunkHash, size_t chunkSize) {
        std::unique_lock<std::shared_mutex> lock(chunkMutex);
        auto it = chunkStore.find(chunkHash);
        if (it != chunkStore.end()) {
            it->second.referenceCount++;
            std::cout << "[BlockServer DEDUP] Chunk " << chunkHash.substr(0, 8) 
                      << " exists in S3. Incremented refs to: " << it->second.referenceCount << "\n";
            return false; // Already existed, deduplicated
        }

        chunkStore[chunkHash] = StoredChunk{chunkHash, chunkSize, 1};
        std::cout << "[BlockServer SAVED] Stored new 4MB block in S3: " << chunkHash.substr(0, 8) << "\n";
        return true;
    }

    // 2. Metadata Server: Commit delta manifest with optimistic version conflict detection
    bool commitFileManifest(const std::string& fileId, int64_t expectedBaseVersion,
                            const std::vector<std::string>& chunkHashes, const std::string& deviceId) {
        std::unique_lock<std::shared_mutex> lock(manifestMutex);
        auto& history = fileRevisions[fileId];
        int64_t currentVersion = history.empty() ? 0 : history.back().versionNumber;

        if (expectedBaseVersion != currentVersion) {
            std::cout << "[CONCURRENCY CONFLICT] Commit rejected on file '" << fileId 
                      << "'! Expected Base: " << expectedBaseVersion 
                      << ", but Cloud is at: " << currentVersion 
                      << " (Triggering Conflicted Copy)\n";
            return false;
        }

        int64_t nextVersion = currentVersion + 1;
        history.push_back(FileVersionManifest{nextVersion, chunkHashes, deviceId, 1727870400});
        std::cout << "[MetadataServer SUCCESS] File '" << fileId 
                  << "' updated to Version " << nextVersion 
                  << " with " << chunkHashes.size() << " chunks by Device " << deviceId << "\n";
        return true;
    }

    // 3. Download/Reconstruct File: Fetch ordered chunk hashes
    std::optional<std::vector<std::string>> getFileChunks(const std::string& fileId) const {
        std::shared_lock<std::shared_mutex> lock(manifestMutex);
        auto it = fileRevisions.find(fileId);
        if (it != fileRevisions.end() && !it->second.empty()) {
            return it->second.back().orderedChunkHashes;
        }
        return std::nullopt;
    }
};

int main() {
    DropboxEngine engine;

    std::string chunkA = "a591a6d40bf420404a011733cfb7b190d62c65bf";
    std::string chunkB = "b38914d40bf420404a011733cfb7b190d62c65bf";
    std::string chunkC_modified = "c77714d40bf420404a011733cfb7b190d62c65bf";

    std::cout << "--- Step 1: Uploading Initial 8MB File (2 chunks) ---\n";
    engine.uploadBlockChunk(chunkA, 4194304);
    engine.uploadBlockChunk(chunkB, 4194304);
    engine.commitFileManifest("project_report.docx", 0, {chunkA, chunkB}, "device_laptop");

    std::cout << "\n--- Step 2: Delta Edit on Laptop (Modifies second chunk only) ---\n";
    // chunkA is unchanged (deduped automatically), chunkC is uploaded
    engine.uploadBlockChunk(chunkA, 4194304); // deduplicated
    engine.uploadBlockChunk(chunkC_modified, 4194304); // new upload
    engine.commitFileManifest("project_report.docx", 1, {chunkA, chunkC_modified}, "device_laptop");

    std::cout << "\n--- Step 3: Desktop Attempts Conflicting Commit with Stale Base Version 1 ---\n";
    // Desktop tries to commit based on Version 1 instead of Version 2
    bool success = engine.commitFileManifest("project_report.docx", 1, {chunkA, chunkB}, "device_desktop");
    if (!success) {
        std::cout << "Client Daemon creating: 'project_report (Desktop's conflicted copy).docx'\n";
    }

    return 0;
}

