import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

enum OrderState { SUBMITTED, PREPARING, OUT_FOR_DELIVERY, DELIVERED }

class Dasher {
    String driverId;
    String name;
    boolean isAvailable;
    double latitude;
    double longitude;

    public Dasher(String id, String name, double lat, double lng) {
        this.driverId = id;
        this.name = name;
        this.isAvailable = true;
        this.latitude = lat;
        this.longitude = lng;
    }
}

class FoodOrder {
    String orderId;
    String userId;
    String restaurantId;
    OrderState status;
    Dasher assignedDasher;

    public FoodOrder(String orderId, String userId, String restaurantId) {
        this.orderId = orderId;
        this.userId = userId;
        this.restaurantId = restaurantId;
        this.status = OrderState.SUBMITTED;
    }
}

class DoorDashService {
    private final Map<String, Dasher> driverFleet = new ConcurrentHashMap<>();
    private final Map<String, FoodOrder> activeOrders = new ConcurrentHashMap<>();

    public void registerDriver(Dasher d) {
        driverFleet.put(d.driverId, d);
    }

    public synchronized FoodOrder createAndDispatchOrder(String orderId, String userId, String restaurantId) {
        FoodOrder order = new FoodOrder(orderId, userId, restaurantId);
        order.status = OrderState.PREPARING;

        // Find nearest available Dasher
        for (Dasher dasher : driverFleet.values()) {
            if (dasher.isAvailable) {
                dasher.isAvailable = false;
                order.assignedDasher = dasher;
                order.status = OrderState.OUT_FOR_DELIVERY;
                System.out.println("Dispatched Dasher: " + dasher.name + " to Order: " + orderId);
                break;
            }
        }
        activeOrders.put(orderId, order);
        return order;
    }
}

