enum class OrderStatus { SUBMITTED, PREPARING, OUT_FOR_DELIVERY, DELIVERED, CANCELLED };

struct GeoLocation {
    double latitude;
    double longitude;

    double distanceTo(const GeoLocation& other) const {
        return std::sqrt(std::pow(latitude - other.latitude, 2) + std::pow(longitude - other.longitude, 2));
    }
};

struct DasherDriver {
    int64_t driverId;
    std::string name;
    GeoLocation location;
    bool isAvailable = true;
};

struct FoodOrderRecord {
    int64_t orderId;
    int64_t customerId;
    int64_t restaurantId;
    int64_t assignedDriverId;
    double totalAmount;
    OrderStatus status;
    std::string timestamp;
};

class DoorDashDispatchEngine {
private:
    std::unordered_map<int64_t, DasherDriver> drivers;
    std::unordered_map<int64_t, FoodOrderRecord> orders;

    mutable std::shared_mutex driverMutex;
    std::mutex orderMutex;
    int64_t orderIdCounter = 1000;

public:
    void registerDriver(int64_t driverId, const std::string& name, double lat, double lng) {
        std::unique_lock<std::shared_mutex> lock(driverMutex);
        drivers[driverId] = DasherDriver{driverId, name, {lat, lng}, true};
        std::cout << "[Driver Registered] " << name << " (ID: " << driverId << ") at (" << lat << ", " << lng << ")\n";
    }

    void updateDriverLocation(int64_t driverId, double lat, double lng) {
        std::unique_lock<std::shared_mutex> lock(driverMutex);
        auto it = drivers.find(driverId);
        if (it != drivers.end()) {
            it->second.location = {lat, lng};
        }
    }

    // Geospatial matching: finds nearest available driver to restaurant location
    std::optional<int64_t> findNearestAvailableDriver(const GeoLocation& restLocation) {
        std::shared_lock<std::shared_mutex> lock(driverMutex);
        int64_t bestDriverId = -1;
        double minDistance = 1e9;

        for (const auto& [id, driver] : drivers) {
            if (driver.isAvailable) {
                double dist = driver.location.distanceTo(restLocation);
                if (dist < minDistance) {
                    minDistance = dist;
                    bestDriverId = id;
                }
            }
        }
        if (bestDriverId != -1) return bestDriverId;
        return std::nullopt;
    }

    int64_t placeOrder(int64_t customerId, int64_t restaurantId, const GeoLocation& restLoc, double amount) {
        int64_t newOrderId;
        {
            std::lock_guard<std::mutex> oLock(orderMutex);
            newOrderId = ++orderIdCounter;
            orders[newOrderId] = FoodOrderRecord{newOrderId, customerId, restaurantId, -1, amount, OrderStatus::SUBMITTED, "2026-10-02T12:00:00Z"};
        }
        std::cout << "[ORDER CREATED] Order ID: " << newOrderId << " | Total: $" << amount << "\n";

        // Attempt driver dispatch
        auto matchedDriverOpt = findNearestAvailableDriver(restLoc);
        if (matchedDriverOpt) {
            int64_t matchedDriverId = *matchedDriverOpt;
            {
                std::unique_lock<std::shared_mutex> dLock(driverMutex);
                drivers[matchedDriverId].isAvailable = false;
            }
            {
                std::lock_guard<std::mutex> oLock(orderMutex);
                orders[newOrderId].assignedDriverId = matchedDriverId;
                orders[newOrderId].status = OrderStatus::OUT_FOR_DELIVERY;
            }
            std::cout << "[DISPATCH SUCCESS] Matched Dasher ID " << matchedDriverId 
                      << " to Order " << newOrderId << "\n";
        } else {
            std::cout << "[DISPATCH QUEUED] No Dasher nearby. Order marked PREPARING in kitchen.\n";
            std::lock_guard<std::mutex> oLock(orderMutex);
            orders[newOrderId].status = OrderStatus::PREPARING;
        }

        return newOrderId;
    }

    std::optional<FoodOrderRecord> getOrderStatus(int64_t orderId) {
        std::lock_guard<std::mutex> lock(orderMutex);
        auto it = orders.find(orderId);
        if (it != orders.end()) return it->second;
        return std::nullopt;
    }
};

int main() {
    DoorDashDispatchEngine engine;

    // 1. Register active Dashers across town
    engine.registerDriver(101, "Dasher Mark", 37.7749, -122.4194); // Near Downtown
    engine.registerDriver(102, "Dasher Sarah", 37.7833, -122.4167); // Further away

    // 2. Customer places order from Italian Bistro
    GeoLocation restaurantLocation{37.7750, -122.4190};
    std::cout << "\n--- Step 1: Placing Order 1 ---\n";
    int64_t o1 = engine.placeOrder(501, 1, restaurantLocation, 34.50);

    // 3. Customer places order 2 (Mark is busy, should assign Sarah)
    std::cout << "\n--- Step 2: Placing Order 2 Concurrently ---\n";
    int64_t o2 = engine.placeOrder(502, 1, restaurantLocation, 22.00);

    // 4. Customer places order 3 (Both Dashers are busy, order queued)
    std::cout << "\n--- Step 3: Placing Order 3 (Fleet Exhausted) ---\n";
    int64_t o3 = engine.placeOrder(503, 1, restaurantLocation, 18.75);

    return 0;
}

