import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class LedgerEntry {
    String entryId;
    String accountId;
    String direction; // DEBIT or CREDIT
    double amount;

    public LedgerEntry(String entryId, String accountId, String direction, double amount) {
        this.entryId = entryId;
        this.accountId = accountId;
        this.direction = direction;
        this.amount = amount;
    }
}

class PayPalPaymentEngine {
    private final Map<String, Double> accountBalances = new ConcurrentHashMap<>();
    private final Map<String, String> idempotencyCache = new ConcurrentHashMap<>();
    private final List<LedgerEntry> globalLedger = Collections.synchronizedList(new ArrayList<>());

    public synchronized boolean executeTransfer(String idempotencyKey, String senderAcc, String receiverAcc, double amount) {
        if (idempotencyCache.containsKey(idempotencyKey)) {
            System.out.println("[IDEMPOTENCY] Returning cached success for key: " + idempotencyKey);
            return true;
        }

        double senderBal = accountBalances.getOrDefault(senderAcc, 0.0);
        if (senderBal < amount) {
            System.out.println("Transfer failed: Insufficient funds in " + senderAcc);
            return false;
        }

        // Double-entry ledger commit
        accountBalances.put(senderAcc, senderBal - amount);
        accountBalances.put(receiverAcc, accountBalances.getOrDefault(receiverAcc, 0.0) + amount);

        globalLedger.add(new LedgerEntry(UUID.randomUUID().toString(), senderAcc, "DEBIT", amount));
        globalLedger.add(new LedgerEntry(UUID.randomUUID().toString(), receiverAcc, "CREDIT", amount));

        idempotencyCache.put(idempotencyKey, "SUCCESS");
        System.out.println("Successfully transferred $" + amount + " from " + senderAcc + " to " + receiverAcc);
        return true;
    }
}

