#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>
#include <chrono>
#include <iomanip>

enum class EntryDirection { DEBIT, CREDIT };
enum class TxnStatus { PENDING, SETTLED, FAILED };

struct LedgerLine {
    int64_t entryId;
    int64_t transactionId;
    int64_t accountId;
    EntryDirection direction;
    double amount;
};

struct PayPalTxnRecord {
    int64_t transactionId;
    int64_t senderId;
    int64_t receiverId;
    double amount;
    std::string currency;
    std::string idempotencyKey;
    TxnStatus status;
    std::string timestamp;
};

class PayPalLedgerService {
private:
    std::unordered_map<int64_t, double> userWallets;                      // userId -> Balance
    std::unordered_map<std::string, PayPalTxnRecord> idempotencyStore;    // idemKey -> Record
    std::vector<LedgerLine> immutableLedger;                              // Append-only ledger
    std::unordered_map<int64_t, PayPalTxnRecord> transactions;            // txnId -> Record

    mutable std::shared_mutex stateMutex;
    int64_t txnIdCounter = 5000;
    int64_t entryIdCounter = 10000;

public:
    void registerAccount(int64_t userId, double initialDeposit) {
        std::unique_lock<std::shared_mutex> lock(stateMutex);
        userWallets[userId] = initialDeposit;
        std::cout << "[Account Created] User " << userId << " with balance: $" << initialDeposit << "\n";
    }

    std::optional<PayPalTxnRecord> transferFunds(const std::string& idempotencyKey,
                                                 int64_t senderId,
                                                 int64_t receiverId,
                                                 double amount,
                                                 const std::string& currency) {
        // 1. Check Idempotency Key (Read Lock)
        {
            std::shared_lock<std::shared_mutex> rLock(stateMutex);
            auto it = idempotencyStore.find(idempotencyKey);
            if (it != idempotencyStore.end()) {
                std::cout << "[IDEMPOTENT HIT] Transaction with key '" << idempotencyKey 
                          << "' already processed. Returning cached receipt.\n";
                return it->second;
            }
        }

        // 2. Acquire Exclusive Write Lock for Atomic Double-Entry Commit
        std::unique_lock<std::shared_mutex> wLock(stateMutex);

        // Double check after write lock
        auto it = idempotencyStore.find(idempotencyKey);
        if (it != idempotencyStore.end()) return it->second;

        auto sIt = userWallets.find(senderId);
        auto rIt = userWallets.find(receiverId);
        if (sIt == userWallets.end() || rIt == userWallets.end()) {
            std::cout << "Transfer rejected: Invalid account ID.\n";
            return std::nullopt;
        }

        if (sIt->second < amount) {
            std::cout << "Transfer rejected: Insufficient funds for User " << senderId 
                      << " (Has: $" << sIt->second << ", Needs: $" << amount << ")\n";
            return std::nullopt;
        }

        // 3. Commit Double-Entry Balances
        sIt->second -= amount;
        rIt->second += amount;

        int64_t newTxnId = ++txnIdCounter;
        immutableLedger.push_back(LedgerLine{++entryIdCounter, newTxnId, senderId, EntryDirection::DEBIT, amount});
        immutableLedger.push_back(LedgerLine{++entryIdCounter, newTxnId, receiverId, EntryDirection::CREDIT, amount});

        PayPalTxnRecord record{
            newTxnId, senderId, receiverId, amount, currency, idempotencyKey, TxnStatus::SETTLED, "2026-10-02T12:00:00Z"
        };

        transactions[newTxnId] = record;
        idempotencyStore[idempotencyKey] = record;

        std::cout << "[TRANSFER SETTLED] Txn ID: " << newTxnId << " | $" << amount 
                  << " " << currency << " transferred from " << senderId << " to " << receiverId << "\n";
        return record;
    }

    double getBalance(int64_t userId) const {
        std::shared_lock<std::shared_mutex> lock(stateMutex);
        auto it = userWallets.find(userId);
        return (it != userWallets.end()) ? it->second : 0.0;
    }
};

int main() {
    PayPalLedgerService paypal;

    int64_t userAlice = 101;
    int64_t userBob = 102;

    // 1. Initialize user balances
    paypal.registerAccount(userAlice, 450.0);
    paypal.registerAccount(userBob, 100.0);

    std::string idempotencyKey1 = "IDEM_TOKEN_PAYPAL_9941";

    std::cout << "\n--- Step 1: Normal Money Transfer ($150) ---\n";
    paypal.transferFunds(idempotencyKey1, userAlice, userBob, 150.0, "USD");
    std::cout << "Alice Balance: $" << paypal.getBalance(userAlice) << "\n";
    std::cout << "Bob Balance: $" << paypal.getBalance(userBob) << "\n";

    std::cout << "\n--- Step 2: Identical Network Retry (Same Idempotency-Key) ---\n";
    // Network drops, client retries exact same request
    paypal.transferFunds(idempotencyKey1, userAlice, userBob, 150.0, "USD");
    std::cout << "Alice Balance (Unchanged): $" << paypal.getBalance(userAlice) << "\n";
    std::cout << "Bob Balance (Unchanged): $" << paypal.getBalance(userBob) << "\n";

    std::cout << "\n--- Step 3: Attempt Overdraft Transfer ($500) ---\n";
    paypal.transferFunds("IDEM_TOKEN_PAYPAL_9942", userAlice, userBob, 500.0, "USD");

    return 0;
}

