import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class HotstarVideo {
    long videoId;
    String title;
    String manifestUrl;
    boolean isLive;

    public HotstarVideo(long id, String title, String url, boolean isLive) {
        this.videoId = id;
        this.title = title;
        this.manifestUrl = url;
        this.isLive = isLive;
    }
}

class PlaybackSessionManager {
    // User ID -> Set of active device IDs
    private final Map<Long, Set<String>> activeScreens = new ConcurrentHashMap<>();
    private final int MAX_CONCURRENT_SCREENS = 2;

    public synchronized boolean acquirePlaybackLease(long userId, String deviceId) {
        Set<String> screens = activeScreens.computeIfAbsent(userId, k -> ConcurrentHashMap.newKeySet());
        if (screens.contains(deviceId)) return true;
        if (screens.size() >= MAX_CONCURRENT_SCREENS) {
            System.out.println("[Playback Blocked] User " + userId + " exceeded maximum screen limit.");
            return false;
        }
        screens.add(deviceId);
        System.out.println("[Lease Granted] Device: " + deviceId + " for User: " + userId);
        return true;
    }

    public void releasePlaybackLease(long userId, String deviceId) {
        Set<String> screens = activeScreens.get(userId);
        if (screens != null) {
            screens.remove(deviceId);
        }
    }
}

