#include <unordered_set>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>
#include <chrono>

struct VideoMetadata {
    int64_t videoId;
    std::string title;
    std::string hlsManifestUrl;
    bool isLiveMatch;
    int durationSeconds;
    int viewCount = 0;
};

class HotstarStreamingEngine {
private:
    std::unordered_map<int64_t, VideoMetadata> catalog;
    std::unordered_map<int64_t, std::unordered_set<std::string>> activeDeviceSessions; // userId -> set(deviceId)
    std::unordered_map<int64_t, int> videoLikes;

    mutable std::shared_mutex catalogMutex;
    std::mutex sessionMutex;
    std::mutex engagementMutex;
    static constexpr size_t MAX_CONCURRENT_SCREENS = 2;

public:
    void ingestVideo(int64_t id, const std::string& title, const std::string& manifestUrl, bool isLive, int duration) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        catalog[id] = VideoMetadata{id, title, manifestUrl, isLive, duration, 0};
        std::cout << "[Content Ingested] Video: '" << title << "' (ID: " << id 
                  << ", Live: " << (isLive ? "YES" : "NO") << ")\n";
    }

    // Enforces strict concurrent device screen limit per account
    bool startPlaybackSession(int64_t userId, const std::string& deviceId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        auto& devices = activeDeviceSessions[userId];

        if (devices.find(deviceId) != devices.end()) {
            return true; // Already leased for this device
        }

        if (devices.size() >= MAX_CONCURRENT_SCREENS) {
            std::cout << "[PLAYBACK DENIED] User " << userId << " exceeded screen quota of " 
                      << MAX_CONCURRENT_SCREENS << " screens!\n";
            return false;
        }

        devices.insert(deviceId);
        std::cout << "[PLAYBACK LEASED] User " << userId << " playing on Device '" << deviceId << "'\n";
        return true;
    }

    void stopPlaybackSession(int64_t userId, const std::string& deviceId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        auto it = activeDeviceSessions.find(userId);
        if (it != activeDeviceSessions.end()) {
            it->second.erase(deviceId);
            std::cout << "[PLAYBACK RELEASED] Device '" << deviceId << "' stopped for User " << userId << "\n";
        }
    }

    std::optional<std::string> streamVideo(int64_t videoId) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        auto it = catalog.find(videoId);
        if (it != catalog.end()) {
            it->second.viewCount++;
            return it->second.hlsManifestUrl;
        }
        return std::nullopt;
    }

    void likeVideo(int64_t videoId) {
        std::lock_guard<std::mutex> lock(engagementMutex);
        videoLikes[videoId]++;
    }

    int getLikeCount(int64_t videoId) {
        std::lock_guard<std::mutex> lock(engagementMutex);
        return videoLikes[videoId];
    }
};

int main() {
    HotstarStreamingEngine engine;

    // 1. Ingest VOD movie and Live Cricket Match
    engine.ingestVideo(101, "Avengers: Endgame", "https://cdn.hotstar.com/vod/avengers/master.m3u8", false, 10800);
    engine.ingestVideo(201, "IND vs AUS World Cup Final", "https://cdn.hotstar.com/live/ind_aus/cmaf.m3u8", true, 28800);

    int64_t userRahul = 5001;

    // 2. User Rahul starts streaming on Mobile Phone (Screen 1)
    std::cout << "\n--- Step 1: User starts streaming on Phone ---\n";
    bool s1 = engine.startPlaybackSession(userRahul, "phone_pixel_7");
    if (s1) {
        auto stream = engine.streamVideo(201);
        std::cout << "Streaming URL: " << stream.value_or("") << "\n";
    }

    // 3. User Rahul starts streaming on Living Room Smart TV (Screen 2)
    std::cout << "\n--- Step 2: User starts streaming on Living Room TV ---\n";
    engine.startPlaybackSession(userRahul, "smart_tv_samsung");

    // 4. Friend attempts to stream on Rahul's account on iPad (Screen 3 - should be rejected)
    std::cout << "\n--- Step 3: Attempting third simultaneous screen (Limit 2) ---\n";
    bool s3 = engine.startPlaybackSession(userRahul, "tablet_ipad_pro");
    if (!s3) {
        std::cout << "Device rejected successfully with 'Screen Limit Exceeded' prompt.\n";
    }

    // 5. User stops TV stream, releases lease, then iPad streams successfully
    std::cout << "\n--- Step 4: Stop TV stream and retry iPad ---\n";
    engine.stopPlaybackSession(userRahul, "smart_tv_samsung");
    engine.startPlaybackSession(userRahul, "tablet_ipad_pro");

    return 0;
}

