    std::vector<int64_t> trackIds;
};

class SpotifyStreamingEngine {
private:
    std::unordered_map<int64_t, TrackMetadata> trackCatalog;
    std::unordered_map<int64_t, UserPlaylist> playlists;
    std::unordered_map<int64_t, std::string> activeConnectDevices; // userId -> deviceId
    std::unordered_map<int64_t, int> trackLikeCounts;

    mutable std::shared_mutex catalogMutex;
    mutable std::shared_mutex playlistMutex;
    std::mutex connectMutex;
    std::mutex likeMutex;
    int64_t trackCounter = 100;
    int64_t playlistCounter = 500;

public:
    int64_t addTrack(const std::string& title, const std::string& artist, int duration) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        int64_t id = ++trackCounter;
        std::string manifest = "https://cdn.spotify.com/hls/" + std::to_string(id) + "/master.m3u8";
        trackCatalog[id] = TrackMetadata{id, title, artist, duration, manifest};
        std::cout << "[Catalog Ingestion] Track: '" << title << "' by " << artist << " (ID: " << id << ")\n";
        return id;
    }

    std::vector<TrackMetadata> searchTracks(const std::string& query) const {
        std::shared_lock<std::shared_mutex> lock(catalogMutex);
        std::vector<TrackMetadata> results;
        std::string lowerQ = query;
        std::transform(lowerQ.begin(), lowerQ.end(), lowerQ.begin(), ::tolower);

        for (const auto& [id, track] : trackCatalog) {
            std::string t = track.title;
            std::string a = track.artist;
            std::transform(t.begin(), t.end(), t.begin(), ::tolower);
            std::transform(a.begin(), a.end(), a.begin(), ::tolower);

            if (t.find(lowerQ) != std::string::npos || a.find(lowerQ) != std::string::npos) {
                results.push_back(track);
            }
        }
        return results;
    }

    int64_t createPlaylist(int64_t userId, const std::string& name) {
        std::unique_lock<std::shared_mutex> lock(playlistMutex);
        int64_t id = ++playlistCounter;
        playlists[id] = UserPlaylist{id, name, userId, {}};
        std::cout << "[Playlist Created] '" << name << "' (ID: " << id << ") by User: " << userId << "\n";
        return id;
    }

    bool addTrackToPlaylist(int64_t playlistId, int64_t trackId) {
        std::unique_lock<std::shared_mutex> lock(playlistMutex);
        auto it = playlists.find(playlistId);
        if (it != playlists.end()) {
            it->second.trackIds.push_back(trackId);
            std::cout << "Added Track " << trackId << " to Playlist " << playlistId << "\n";
            return true;
        }
        return false;
    }

    // Spotify Connect: Transfer playback device seamlessly
    void switchPlaybackDevice(int64_t userId, const std::string& targetDeviceId) {
        std::lock_guard<std::mutex> lock(connectMutex);
        activeConnectDevices[userId] = targetDeviceId;
        std::cout << "[Spotify Connect] Active audio device for User " << userId 
                  << " switched to: '" << targetDeviceId << "'\n";
    }

    void likeTrack(int64_t trackId) {
        std::lock_guard<std::mutex> lock(likeMutex);
        trackLikeCounts[trackId]++;
    }

    int getTrackLikes(int64_t trackId) {
        std::lock_guard<std::mutex> lock(likeMutex);
        return trackLikeCounts[trackId];
    }
};

int main() {
    SpotifyStreamingEngine spotify;

    // 1. Ingest tracks
    int64_t t1 = spotify.addTrack("Starboy", "The Weeknd", 230);
    int64_t t2 = spotify.addTrack("Blinding Lights", "The Weeknd", 200);
    int64_t t3 = spotify.addTrack("Levitating", "Dua Lipa", 203);

    // 2. Search catalog
    std::cout << "\n--- Step 1: Searching for 'Weeknd' ---\n";
    auto matches = spotify.searchTracks("Weeknd");
    for (const auto& track : matches) {
        std::cout << "Found: " << track.title << " by " << track.artist 
                  << " | Stream: " << track.streamManifestUrl << "\n";
    }

    // 3. User creates playlist and adds songs
