    spotify.addTrackToPlaylist(plId, t1);
    spotify.addTrackToPlaylist(plId, t2);

    // 4. Spotify Connect: Transfer playback from phone to smart speaker
    std::cout << "\n--- Step 2: Spotify Connect Handover ---\n";
    spotify.switchPlaybackDevice(aliceId, "iPhone 16 Pro");
    spotify.switchPlaybackDevice(aliceId, "Sonos Living Room Speaker");

    // 5. Engagement: Like a track
    spotify.likeTrack(t2);
