import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

class WeChatSyncMessage {
    String messageId;
    String senderId;
    String receiverId;
    long sequenceId;
    String content;

    public WeChatSyncMessage(String msgId, String sender, String receiver, long seq, String text) {
        this.messageId = msgId;
        this.senderId = sender;
        this.receiverId = receiver;
        this.sequenceId = seq;
        this.content = text;
    }
}

class WeChatSyncEngine {
    // User ID -> Monotonic Sequence Generator
    private final Map<String, AtomicLong> userSeqGenerators = new ConcurrentHashMap<>();
    // User ID -> List of Sync Messages
    private final Map<String, List<WeChatSyncMessage>> userMailboxes = new ConcurrentHashMap<>();

    public synchronized WeChatSyncMessage sendMessage(String senderId, String receiverId, String text) {
        AtomicLong seqGen = userSeqGenerators.computeIfAbsent(receiverId, k -> new AtomicLong(0));
        long newSeq = seqGen.incrementAndGet();

        String msgId = UUID.randomUUID().toString().substring(0, 8);
        WeChatSyncMessage msg = new WeChatSyncMessage(msgId, senderId, receiverId, newSeq, text);

        userMailboxes.computeIfAbsent(receiverId, k -> Collections.synchronizedList(new ArrayList<>())).add(msg);
        System.out.println("[Sync Protocol] Assigned seq_id=" + newSeq + " for receiver: " + receiverId);
        return msg;
    }

    public List<WeChatSyncMessage> syncDelta(String receiverId, long clientSyncKey) {
        List<WeChatSyncMessage> all = userMailboxes.getOrDefault(receiverId, Collections.emptyList());
        List<WeChatSyncMessage> deltas = new ArrayList<>();
        for (WeChatSyncMessage m : all) {
            if (m.sequenceId > clientSyncKey) {
                deltas.add(m);
            }
        }
        return deltas;
    }
}

