#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>
#include <algorithm>

struct SyncPacket {
    std::string messageId;
    std::string senderId;
    std::string receiverId;
    int64_t sequenceId;
    std::string content;
};

struct MomentInteraction {
    std::string userId;
    std::string text;
};

struct MomentItem {
    std::string momentId;
    std::string authorId;
    std::string caption;
    std::vector<MomentInteraction> comments;
};

class WeChatPlatformEngine {
private:
    // WeChat Sync Protocol: receiverId -> current monotonic sequence
    std::unordered_map<std::string, int64_t> userSyncKeys;
    // receiverId -> list of stored sync packets
    std::unordered_map<std::string, std::vector<SyncPacket>> userMailboxes;
    // Moments store: momentId -> MomentItem
    std::unordered_map<std::string, MomentItem> moments;
    // Social Graph: userId -> set of friendIds
    std::unordered_map<std::string, std::unordered_set<std::string>> friendships;

    mutable std::shared_mutex syncMutex;
    mutable std::shared_mutex momentMutex;
    mutable std::shared_mutex friendMutex;
    int64_t idCounter = 1000;

public:
    void addFriendship(const std::string& u1, const std::string& u2) {
        std::unique_lock<std::shared_mutex> lock(friendMutex);
        friendships[u1].insert(u2);
        friendships[u2].insert(u1);
    }

    // 1. WeChat Sync Protocol: Send Message with Monotonic Sequence Assignment
    SyncPacket sendMessage(const std::string& senderId, const std::string& receiverId, const std::string& content) {
        std::unique_lock<std::shared_mutex> lock(syncMutex);
        int64_t nextSeq = ++userSyncKeys[receiverId];
        std::string msgId = "msg_" + std::to_string(++idCounter);

        SyncPacket packet{msgId, senderId, receiverId, nextSeq, content};
        userMailboxes[receiverId].push_back(packet);

        std::cout << "[SYNC PROTOCOL] Message '" << content << "' routed to " << receiverId 
                  << " with assigned Sequence ID: " << nextSeq << "\n";
        return packet;
    }

    // Client pulls delta messages where seq > client_sync_key
    std::vector<SyncPacket> pullDeltaSync(const std::string& receiverId, int64_t clientSyncKey) const {
        std::shared_lock<std::shared_mutex> lock(syncMutex);
        std::vector<SyncPacket> deltas;
        auto it = userMailboxes.find(receiverId);
        if (it != userMailboxes.end()) {
            for (const auto& pkt : it->second) {
                if (pkt.sequenceId > clientSyncKey) {
                    deltas.push_back(pkt);
                }
            }
        }
        return deltas;
    }

    // 2. Moments: Post Moment and add Comment
    std::string postMoment(const std::string& authorId, const std::string& caption) {
        std::unique_lock<std::shared_mutex> lock(momentMutex);
        std::string mId = "mmt_" + std::to_string(++idCounter);
        moments[mId] = MomentItem{mId, authorId, caption, {}};
        std::cout << "[MOMENT PUBLISHED] ID: " << mId << " by Author " << authorId << "\n";
        return mId;
    }

    void commentOnMoment(const std::string& momentId, const std::string& commenterId, const std::string& text) {
        std::unique_lock<std::shared_mutex> lock(momentMutex);
        auto it = moments.find(momentId);
        if (it != moments.end()) {
            it->second.comments.push_back(MomentInteraction{commenterId, text});
            std::cout << "User " << commenterId << " commented on Moment " << momentId << "\n";
        }
    }

    // 3. Moments Privacy Gatekeeper: Filter comments by mutual friendship
    std::vector<MomentInteraction> getVisibleComments(const std::string& momentId, const std::string& viewerId) const {
        std::shared_lock<std::shared_mutex> mLock(momentMutex);
        std::shared_lock<std::shared_mutex> fLock(friendMutex);

        std::vector<MomentInteraction> visible;
        auto mIt = moments.find(momentId);
        if (mIt == moments.end()) return visible;

        const auto& viewerFriends = friendships.at(viewerId);

        for (const auto& comment : mIt->second.comments) {
            // Rule: Viewer sees comment if viewer authored it, or commenter is a mutual friend
            if (comment.userId == viewerId || viewerFriends.find(comment.userId) != viewerFriends.end()) {
                visible.push_back(comment);
            }
        }
        return visible;
    }
};

int main() {
    WeChatPlatformEngine wechat;

    std::string alice = "user_alice";
    std::string bob = "user_bob";       // Friend of Alice
    std::string charlie = "user_charlie"; // Friend of Alice, but NOT friend of Bob

    // Establish social graph
    wechat.addFriendship(alice, bob);
    wechat.addFriendship(alice, charlie);
    // Notice: Bob and Charlie are NOT friends!

    std::cout << "--- 1. Testing WeChat Sync Protocol ---\n";
    wechat.sendMessage(alice, bob, "Hi Bob!");       // seq = 1
    wechat.sendMessage(alice, bob, "Are you free?"); // seq = 2

    // Bob pulls missed updates starting from sync_key = 0
    auto deltaPackets = wechat.pullDeltaSync(bob, 0);
    std::cout << "Bob pulled " << deltaPackets.size() << " delta messages from server.\n";

    std::cout << "\n--- 2. Testing Moments Mutual-Friend Privacy Filtering ---\n";
    std::string momentId = wechat.postMoment(alice, "Weekend hiking in Hangzhou!");

    // Bob and Charlie both comment on Alice's post
    wechat.commentOnMoment(momentId, bob, "Great view, Alice!");
    wechat.commentOnMoment(momentId, charlie, "Looks fun!");

    // Bob views Alice's Moment comments
    std::cout << "\n[Bob viewing Alice's Moment comments]:\n";
    auto bobSees = wechat.getVisibleComments(momentId, bob);
    for (const auto& c : bobSees) {
        std::cout << "- " << c.userId << ": " << c.text << "\n";
    }
    // Bob sees his own comment, but NOT Charlie's comment (because Bob and Charlie are not friends)

    // Charlie views Alice's Moment comments
    std::cout << "\n[Charlie viewing Alice's Moment comments]:\n";
    auto charlieSees = wechat.getVisibleComments(momentId, charlie);
    for (const auto& c : charlieSees) {
        std::cout << "- " << c.userId << ": " << c.text << "\n";
    }
    // Charlie sees his own comment, but NOT Bob's comment

    return 0;
}

