import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class WeiboPost {
    long postId;
    long userId;
    String content;
    long timestamp;

    public WeiboPost(long postId, long userId, String content) {
        this.postId = postId;
        this.userId = userId;
        this.content = content;
        this.timestamp = System.currentTimeMillis();
    }
}

class WeiboTimelineService {
    private final Map<Long, WeiboPost> posts = new ConcurrentHashMap<>();
    private final Map<Long, Set<Long>> followingGraph = new ConcurrentHashMap<>();
    private final Map<Long, List<Long>> userInboxes = new ConcurrentHashMap<>(); // Fanout push inbox

    public void follow(long followerId, long followingId) {
        followingGraph.computeIfAbsent(followerId, k -> ConcurrentHashMap.newKeySet()).add(followingId);
    }

    // Hybrid post publish
    public synchronized void publishPost(WeiboPost post, boolean isCelebrity) {
        posts.put(post.postId, post);
        if (!isCelebrity) {
            // Fanout-on-Write: Push to all follower inboxes
            for (Map.Entry<Long, Set<Long>> entry : followingGraph.entrySet()) {
