class WeiboSystemEngine {
private:
    std::unordered_map<int64_t, WeiboPostItem> postsTable;
    std::unordered_map<int64_t, std::unordered_set<int64_t>> followees; // followerId -> set of followingIds
    std::unordered_map<int64_t, std::unordered_set<int64_t>> followers; // authorId -> set of followerIds
    std::unordered_map<int64_t, std::vector<int64_t>> pushInboxes;      // userId -> list of postIds
    std::unordered_set<int64_t> celebrityAccounts;                     // Authors with > 50K followers

    mutable std::shared_mutex postMutex;
    mutable std::shared_mutex socialMutex;
    std::mutex inboxMutex;
    int64_t postIdCounter = 1000;

public:
    void registerCelebrity(int64_t authorId) {
        std::unique_lock<std::shared_mutex> lock(socialMutex);
        celebrityAccounts.insert(authorId);
    }

    void followUser(int64_t followerId, int64_t targetId) {
        std::unique_lock<std::shared_mutex> lock(socialMutex);
        followees[followerId].insert(targetId);
        followers[targetId].insert(followerId);
        std::cout << "User " << followerId << " followed User " << targetId << "\n";
    }

    // Hybrid Feed Fanout: Push for normal users, Pull for celebrities
    int64_t publishPost(int64_t authorId, const std::string& content) {
        int64_t newPostId;
        auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        {
            std::unique_lock<std::shared_mutex> lock(postMutex);
            newPostId = ++postIdCounter;
            postsTable[newPostId] = WeiboPostItem{newPostId, authorId, content, now, 0};
        }

        bool isCeleb = false;
        std::vector<int64_t> targetFollowers;
        {
            std::shared_lock<std::shared_mutex> lock(socialMutex);
            isCeleb = (celebrityAccounts.find(authorId) != celebrityAccounts.end());
            if (!isCeleb && followers.find(authorId) != followers.end()) {
                targetFollowers.assign(followers.at(authorId).begin(), followers.at(authorId).end());
            }
        }

        if (!isCeleb) {
            // Fanout-on-Write (Push into active follower inboxes)
            std::lock_guard<std::mutex> iLock(inboxMutex);
            for (int64_t fId : targetFollowers) {
                pushInboxes[fId].push_back(newPostId);
            }
            std::cout << "[FANOUT PUSH] Post " << newPostId << " pushed to " 
                      << targetFollowers.size() << " follower inboxes.\n";
        } else {
            std::cout << "[CELEBRITY PULL] Post " << newPostId 
                      << " saved. Skipped push fanout to protect IOPS.\n";
        }

        return newPostId;
    }

    // Merge read timeline (Pushed inboxes + Pulled celebrity posts)
    std::vector<WeiboPostItem> getTimeline(int64_t userId) const {
        std::vector<int64_t> candidatePostIds;
        {
            std::lock_guard<std::mutex> iLock(const_cast<std::mutex&>(inboxMutex));
            auto it = pushInboxes.find(userId);
            if (it != pushInboxes.end()) candidatePostIds = it->second;
        }

        std::unordered_set<int64_t> followedCelebs;
        {
            std::shared_lock<std::shared_mutex> sLock(socialMutex);
            auto it = followees.find(userId);
            if (it != followees.end()) {
                for (int64_t fId : it->second) {
                    if (celebrityAccounts.find(fId) != celebrityAccounts.end()) {
                        followedCelebs.insert(fId);
                    }
                }
            }
        }

        std::shared_lock<std::shared_mutex> pLock(postMutex);
        std::vector<WeiboPostItem> result;
        for (int64_t pId : candidatePostIds) {
            auto it = postsTable.find(pId);
            if (it != postsTable.end()) result.push_back(it->second);
        }

        // Pull posts from followed celebrities dynamically
        for (const auto& [pId, post] : postsTable) {
            if (followedCelebs.find(post.authorId) != followedCelebs.end()) {
                result.push_back(post);
            }
        }

        std::sort(result.begin(), result.end(), [](const WeiboPostItem& a, const WeiboPostItem& b) {
            return a.timestamp > b.timestamp;
        });

        return result;
    }
};

int main() {
    WeiboSystemEngine weibo;

    int64_t userNormal = 101;
    int64_t userCelebrity = 999;
    int64_t followerBob = 201;

    weibo.registerCelebrity(userCelebrity);

    // Bob follows both a normal user and a celebrity
    weibo.followUser(followerBob, userNormal);
    weibo.followUser(followerBob, userCelebrity);

    std::cout << "\n--- 1. Normal user posts (Fanout Push) ---\n";
    weibo.publishPost(userNormal, "Having coffee on a sunny day!");

    std::cout << "\n--- 2. Celebrity posts (Pull Strategy) ---\n";
    weibo.publishPost(userCelebrity, "New movie premiering worldwide tonight! #Excited");

    std::cout << "\n--- 3. Bob opens his Timeline feed (Merged) ---\n";
    auto feed = weibo.getTimeline(followerBob);
    for (const auto& post : feed) {
        std::cout << "[Post ID: " << post.postId << "] Author: " << post.authorId 
                  << " | Content: " << post.content << "\n";
    }

    return 0;
}

