        this.cdnUrl = url;
        this.tags = tags;
        this.likesCount = 0;
        this.downloadCount = 0;
    }
}

class UnsplashService {
    private final Map<String, PhotoMetadata> photoCatalog = new ConcurrentHashMap<>();
    private final Map<String, Long> downloadCounterBuffer = new ConcurrentHashMap<>();

    public void indexPhoto(PhotoMetadata photo) {
        photoCatalog.put(photo.imageId, photo);
    }

    public List<PhotoMetadata> searchByTag(String queryTag) {
        List<PhotoMetadata> matched = new ArrayList<>();
        for (PhotoMetadata p : photoCatalog.values()) {
            if (p.tags.contains(queryTag.toLowerCase()) || p.title.toLowerCase().contains(queryTag.toLowerCase())) {
                matched.add(p);
            }
        }
        return matched;
    }

    // Buffered Atomic Download Incrementation
    public synchronized String trackAndGetDownloadUrl(String imageId) {
        PhotoMetadata p = photoCatalog.get(imageId);
        if (p != null) {
            p.downloadCount++;
            downloadCounterBuffer.merge(imageId, 1L, Long::sum);
            System.out.println("[Telemetry] Image " + imageId + " downloaded. Total: " + p.downloadCount);
            return p.cdnUrl + "?force=download";
        }
        return null;
    }
}

