class UnsplashSystemEngine {
private:
    std::unordered_map<std::string, ImageItem> imageCatalog;
    std::unordered_map<std::string, std::unordered_set<std::string>> tagInvertedIndex; // tag -> set of imageIds
    std::unordered_map<std::string, uint64_t> downloadBuffer;                         // In-memory counter buffer

    mutable std::shared_mutex catalogMutex;
    mutable std::shared_mutex indexMutex;
    std::mutex downloadMutex;
    int64_t imageCounter = 1000;

public:
    std::string publishImage(const std::string& photographerId, const std::string& title,
                             const std::vector<std::string>& tags, const std::string& blurhash) {
        std::unique_lock<std::shared_mutex> cLock(catalogMutex);
        std::unique_lock<std::shared_mutex> iLock(indexMutex);

        std::string imgId = "img_" + std::to_string(++imageCounter);
        std::string rawKey = "s3://unsplash-raw/" + imgId + ".tiff";
        std::string cdnUrl = "https://images.unsplash.com/" + imgId + ".webp";

        ImageItem item{imgId, photographerId, title, rawKey, cdnUrl, blurhash, tags, 0, 0};
        imageCatalog[imgId] = item;

        for (const auto& tag : tags) {
            std::string lowerTag = tag;
            std::transform(lowerTag.begin(), lowerTag.end(), lowerTag.begin(), ::tolower);
            tagInvertedIndex[lowerTag].insert(imgId);
        }

        std::cout << "[IMAGE INGESTED] ID: " << imgId << " | '" << title 
                  << "' | BlurHash: " << blurhash << "\n";
        return imgId;
    }

    std::vector<ImageItem> searchImages(const std::string& keyword) const {
        std::string lowerKeyword = keyword;
        std::transform(lowerKeyword.begin(), lowerKeyword.end(), lowerKeyword.begin(), ::tolower);

        std::unordered_set<std::string> matchedIds;
        {
            std::shared_lock<std::shared_mutex> iLock(indexMutex);
            auto it = tagInvertedIndex.find(lowerKeyword);
            if (it != tagInvertedIndex.end()) {
                matchedIds = it->second;
            }
        }

        std::shared_lock<std::shared_mutex> cLock(catalogMutex);
        std::vector<ImageItem> results;
        for (const auto& id : matchedIds) {
            results.push_back(imageCatalog.at(id));
        }
        return results;
    }

    // Thread-safe download tracking with buffer aggregation
    std::optional<std::string> triggerDownload(const std::string& imageId) {
        std::unique_lock<std::shared_mutex> cLock(catalogMutex);
        auto it = imageCatalog.find(imageId);
        if (it == imageCatalog.end()) {
            std::cout << "Download failed: Image not found.\n";
            return std::nullopt;
        }

        it->second.downloadCount++;
        {
            std::lock_guard<std::mutex> dLock(downloadMutex);
            downloadBuffer[imageId]++;
        }

        std::cout << "[TELEMETRY] Image '" << it->second.title << "' downloaded. Total downloads: " 
                  << it->second.downloadCount << "\n";
        return it->second.cdnWebpUrl + "?dl=true&q=100";
    }
};

