    std::string img1 = engine.publishImage(photographer, "Misty Yosemite Sunrise", 
                                          {"nature", "mountains", "sunrise", "mist"}, "L6Pj{^jE.AyE");
    std::string img2 = engine.publishImage(photographer, "Cyberpunk Neon Alley", 
                                          {"urban", "night", "neon", "city"}, "U48q_3?b_3%M");

