import java.util.concurrent.ConcurrentHashMap;

enum DriverStatus { AVAILABLE, ON_TRIP, OFFLINE }
enum RideStatus { REQUESTED, ACCEPTED, IN_PROGRESS, COMPLETED, CANCELLED }

class GeoPoint {
    double latitude;
    double longitude;
    public GeoPoint(double lat, double lng) {
        this.latitude = lat;
        this.longitude = lng;
    }
    public double distanceTo(GeoPoint other) {
        double dLat = Math.toRadians(other.latitude - this.latitude);
        double dLng = Math.toRadians(other.longitude - this.longitude);
        double a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
                   Math.cos(Math.toRadians(this.latitude)) * Math.cos(Math.toRadians(other.latitude)) *
                   Math.sin(dLng / 2) * Math.sin(dLng / 2);
        return 6371.0 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    }
}

class UberDriver {
    long driverId;
    String name;
    GeoPoint location;
    DriverStatus status;

    public UberDriver(long id, String name, GeoPoint loc) {
        this.driverId = id;
        this.name = name;
        this.location = loc;
        this.status = DriverStatus.AVAILABLE;
    }
}

class UberDispatchService {
    private final Map<Long, UberDriver> drivers = new ConcurrentHashMap<>();

    public void registerDriver(UberDriver d) {
        drivers.put(d.driverId, d);
    }

    public synchronized UberDriver dispatchNearestDriver(GeoPoint pickup) {
        UberDriver nearest = null;
        double minDistance = Double.MAX_VALUE;

        for (UberDriver d : drivers.values()) {
            if (d.status == DriverStatus.AVAILABLE) {
                double dist = d.location.distanceTo(pickup);
                if (dist < minDistance && dist <= 5.0) { // 5km pickup radius
                    minDistance = dist;
                    nearest = d;
                }
            }
        }

        if (nearest != null) {
            nearest.status = DriverStatus.ON_TRIP;
            System.out.println("Dispatched Driver: " + nearest.name + " (Dist: " + minDistance + " km)");
        }
        return nearest;
    }
}

