#include <cmath>
#include <optional>
#include <chrono>

enum class DriverStatus { AVAILABLE, ON_TRIP, OFFLINE };
enum class TripStatus { REQUESTED, ACCEPTED, IN_PROGRESS, COMPLETED, CANCELLED };

struct GeoCoord {
    double latitude;
    double longitude;

    // Haversine distance in kilometers
    double distanceTo(const GeoCoord& other) const {
        constexpr double R = 6371.0;
        double dLat = (other.latitude - latitude) * M_PI / 180.0;
        double dLng = (other.longitude - longitude) * M_PI / 180.0;
        double a = std::sin(dLat / 2) * std::sin(dLat / 2) +
                   std::cos(latitude * M_PI / 180.0) * std::cos(other.latitude * M_PI / 180.0) *
                   std::sin(dLng / 2) * std::sin(dLng / 2);
        double c = 2 * std::atan2(std::sqrt(a), std::sqrt(1 - a));
        return R * c;
    }
};

struct DriverState {
    int64_t driverId;
    std::string name;
    GeoCoord location;
    DriverStatus status;
    int64_t lastPingTimestamp;
};

struct RideTrip {
    int64_t tripId;
    int64_t riderId;
    int64_t driverId;
    GeoCoord pickup;
    GeoCoord dropoff;
    double fare;
    TripStatus status;
};

class UberDispatchEngine {
private:
    std::unordered_map<int64_t, DriverState> drivers; // driverId -> DriverState
    std::unordered_map<int64_t, RideTrip> trips;       // tripId -> RideTrip

    mutable std::shared_mutex driverMutex;
    std::mutex tripMutex;
    int64_t tripIdCounter = 1000;

public:
    // Driver GPS telemetry ping every 4s
    void updateDriverLocation(int64_t driverId, const std::string& name, double lat, double lng) {
        std::unique_lock<std::shared_mutex> lock(driverMutex);
        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        auto it = drivers.find(driverId);
        if (it != drivers.end()) {
            it->second.location = {lat, lng};
            it->second.lastPingTimestamp = now;
        } else {
            drivers[driverId] = DriverState{driverId, name, {lat, lng}, DriverStatus::AVAILABLE, now};
        }
    }

    // DISCO Matching: Queries nearest available driver within radius
    std::optional<int64_t> findNearestDriver(const GeoCoord& pickupLocation, double radiusKm = 5.0) {
        std::shared_lock<std::shared_mutex> lock(driverMutex);
        int64_t bestDriverId = -1;
        double minDistance = 1e9;

        for (const auto& [id, driver] : drivers) {
            if (driver.status == DriverStatus::AVAILABLE) {
                double dist = driver.location.distanceTo(pickupLocation);
                if (dist < minDistance && dist <= radiusKm) {
                    minDistance = dist;
                    bestDriverId = id;
                }
            }
        }

        if (bestDriverId != -1) return bestDriverId;
        return std::nullopt;
    }

    // Books ride and executes dispatch assignment
    std::optional<int64_t> requestRide(int64_t riderId, const GeoCoord& pickup, const GeoCoord& dropoff) {
        double tripDistance = pickup.distanceTo(dropoff);
        double baseFare = 2.50 + (1.20 * tripDistance);

        auto matchedDriverOpt = findNearestDriver(pickup, 6.0);
        if (!matchedDriverOpt) {
            std::cout << "[DISPATCH FAILED] No drivers available near pickup location!\n";
            return std::nullopt;
        }

        int64_t assignedDriverId = *matchedDriverOpt;
        {
            std::unique_lock<std::shared_mutex> dLock(driverMutex);
            drivers[assignedDriverId].status = DriverStatus::ON_TRIP;
        }

        int64_t newTripId;
        {
            std::lock_guard<std::mutex> tLock(tripMutex);
            newTripId = ++tripIdCounter;
            trips[newTripId] = RideTrip{newTripId, riderId, assignedDriverId, pickup, dropoff, baseFare, TripStatus::ACCEPTED};
        }

        std::cout << "[RIDE BOOKED] Trip " << newTripId << " matched with Driver " 
                  << assignedDriverId << " | Distance: " << tripDistance << " km | Fare: $" << baseFare << "\n";
        return newTripId;
    }

    void completeTrip(int64_t tripId) {
        std::lock_guard<std::mutex> tLock(tripMutex);
        auto it = trips.find(tripId);
        if (it != trips.end() && it->second.status == TripStatus::ACCEPTED) {
            it->second.status = TripStatus::COMPLETED;
            int64_t dId = it->second.driverId;
            {
                std::unique_lock<std::shared_mutex> dLock(driverMutex);
                drivers[dId].status = DriverStatus::AVAILABLE;
            }
            std::cout << "[TRIP COMPLETED] Trip " << tripId << " finished. Driver " << dId << " is now AVAILABLE.\n";
        }
    }
};

int main() {
    UberDispatchEngine engine;

    // 1. Ingest GPS pings for two drivers (Chennai coordinates)
    engine.updateDriverLocation(501, "Murugan", 13.0827, 80.2707); // Central Station
    engine.updateDriverLocation(502, "Karthik", 13.0400, 80.2500); // T. Nagar

    // 2. Rider requests trip from Central Station to Airport
    GeoCoord pickup{13.0830, 80.2710};
    GeoCoord dropoff{12.9800, 80.2200};

    std::cout << "--- Step 1: Rider requests cab near Central Station ---\n";
    auto trip1 = engine.requestRide(101, pickup, dropoff);

    // 3. Second rider requests cab in the same area (Murugan is busy, Karthik is further away)
    std::cout << "\n--- Step 2: Second rider requests cab ---\n";
    auto trip2 = engine.requestRide(102, pickup, dropoff);

    // 4. Trip 1 completes
    if (trip1) {
        std::cout << "\n--- Step 3: Complete Trip 1 ---\n";
        engine.completeTrip(*trip1);
    }

    return 0;
}

