import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

class SlackMessage {
    private final long messageId;
    private final long channelId;
    private final long senderId;
    private final String content;
    private final long timestamp;

    public SlackMessage(long messageId, long channelId, long senderId, String content) {
        this.messageId = messageId;
        this.channelId = channelId;
        this.senderId = senderId;
        this.content = content;
        this.timestamp = System.currentTimeMillis();
    }
    public long getMessageId() { return messageId; }
    public long getChannelId() { return channelId; }
    public String getContent() { return content; }
}

class SlackGatewayEngine {
    // Thread-safe channel membership & message buffering
    private final Map<Long, List<SlackMessage>> channelMessageLog = new ConcurrentHashMap<>();
    private final Map<Long, Set<Long>> channelMembers = new ConcurrentHashMap<>();
    private final AtomicLong messageIdSequence = new AtomicLong(1000L);

    public void joinChannel(long channelId, long userId) {
        channelMembers.computeIfAbsent(channelId, k -> ConcurrentHashMap.newKeySet()).add(userId);
    }

    public SlackMessage publishMessage(long channelId, long senderId, String content) {
        long newId = messageIdSequence.incrementAndGet();
        SlackMessage msg = new SlackMessage(newId, channelId, senderId, content);

        // Append message atomically to channel log
        channelMessageLog.computeIfAbsent(channelId, k -> new CopyOnWriteArrayList<>()).add(msg);

        // Fanout notification simulation
        Set<Long> members = channelMembers.getOrDefault(channelId, Collections.emptySet());
        System.out.println("[FANOUT] Message " + newId + " broadcasted to " + members.size() + " members in Channel " + channelId);
        return msg;
    }

    public List<SlackMessage> getRecentMessages(long channelId, int limit) {
        List<SlackMessage> history = channelMessageLog.getOrDefault(channelId, Collections.emptyList());
        int size = history.size();
        return history.subList(Math.max(0, size - limit), size);
    }
}

