    check_in = request.args.get('check_in_date')
    check_out = request.args.get('check_out_date')

    results = []
    with db_lock:
        for prop_id, prop in properties_db.items():
            if location and location not in prop['location'].lower():
                continue
            if max_price and prop['price'] > max_price:
