import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

class Listing {
    long propertyId;
    long hostId;
    String title;
    double pricePerNight;
    public Listing(long id, long hostId, String title, double price) {
        this.propertyId = id;
        this.hostId = hostId;
        this.title = title;
        this.pricePerNight = price;
    }
}

class Reservation {
    long bookingId;
    long propertyId;
    long guestId;
    LocalDate checkIn;
    LocalDate checkOut;
    public Reservation(long bId, long pId, long gId, LocalDate in, LocalDate out) {
        this.bookingId = bId;
        this.propertyId = pId;
        this.guestId = gId;
        this.checkIn = in;
        this.checkOut = out;
    }
    public boolean overlapsWith(LocalDate start, LocalDate end) {
        return (start.isBefore(this.checkOut) && end.isAfter(this.checkIn));
    }
}

class AirbnbBookingEngine {
    private final Map<Long, Listing> listings = new ConcurrentHashMap<>();
    private final Map<Long, List<Reservation>> propertyReservations = new ConcurrentHashMap<>();
    // Fine-grained lock per property to prevent global locking bottlenecks
    private final ConcurrentHashMap<Long, ReentrantLock> propertyLocks = new ConcurrentHashMap<>();
    private long bookingSequence = 1000L;

    public void addListing(Listing l) {
        listings.put(l.propertyId, l);
        propertyReservations.put(l.propertyId, new CopyOnWriteArrayList<>());
        propertyLocks.put(l.propertyId, new ReentrantLock());
    }

    // Thread-safe atomic booking to eliminate double-booking
    public Reservation bookStay(long propertyId, long guestId, LocalDate checkIn, LocalDate checkOut) throws Exception {
        if (!listings.containsKey(propertyId)) {
            throw new IllegalArgumentException("Listing does not exist!");
        }
        if (!checkIn.isBefore(checkOut)) {
            throw new IllegalArgumentException("Check-in must be strictly before check-out!");
        }

        ReentrantLock lock = propertyLocks.computeIfAbsent(propertyId, k -> new ReentrantLock());
        lock.lock(); // Lock this specific property
        try {
            List<Reservation> existing = propertyReservations.get(propertyId);
            for (Reservation r : existing) {
                if (r.overlapsWith(checkIn, checkOut)) {
                    throw new IllegalStateException("Selected dates already booked!");
                }
            }
            Reservation newReservation = new Reservation(++bookingSequence, propertyId, guestId, checkIn, checkOut);
            existing.add(newReservation);
            System.out.println("[SUCCESS] Booking " + newReservation.bookingId + " confirmed for Property " + propertyId);
            return newReservation;
        } finally {
            lock.unlock();
        }
    }
}

