import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

enum VideoPrivacy { PUBLIC, PRIVATE, PASSWORD, DOMAIN_RESTRICTED }

class VideoManifest {
    final String videoId;
    final String title;
    final VideoPrivacy privacy;
    final Set<String> allowedDomains;
    final String hlsUrl;
    final AtomicLong views = new AtomicLong(0);

    public VideoManifest(String id, String title, VideoPrivacy privacy, Set<String> domains, String hls) {
        this.videoId = id;
        this.title = title;
        this.privacy = privacy;
        this.allowedDomains = domains != null ? domains : Collections.emptySet();
        this.hlsUrl = hls;
    }
}

class VimeoPlaybackEngine {
    private final Map<String, VideoManifest> videoCatalog = new ConcurrentHashMap<>();
    // In-memory high throughput buffer for analytics writes (34.7K QPS handling)
    private final ConcurrentLinkedQueue<String> playbackLogBuffer = new ConcurrentLinkedQueue<>();

    public void registerVideo(VideoManifest v) {
        videoCatalog.put(v.videoId, v);
    }

    // Sub-50ms playback verification and token dispatching
    public String authorizeAndStream(String videoId, String requestRefererDomain) throws SecurityException {
        VideoManifest video = videoCatalog.get(videoId);
        if (video == null) {
            throw new NoSuchElementException("Video does not exist!");
        }

        // Domain-lock access control check
        if (video.privacy == VideoPrivacy.DOMAIN_RESTRICTED) {
            if (requestRefererDomain == null || !video.allowedDomains.contains(requestRefererDomain)) {
                throw new SecurityException("Access Denied: Domain " + requestRefererDomain + " is not authorized to embed this video!");
            }
        }

        // Atomic view count update and non-blocking log write
        video.views.incrementAndGet();
        playbackLogBuffer.offer(videoId);

        return video.hlsUrl + "?token=hmac_secure_" + System.currentTimeMillis();
    }

    public long getViews(String videoId) {
        VideoManifest v = videoCatalog.get(videoId);
        return v != null ? v.views.get() : 0L;
    }
}

