users_db = {}
transactions_db = {}
likes_db = {}     # tx_id -> set of user_ids
comments_db = {}  # tx_id -> list of comment dicts
idempotency_keys = {} # key -> response

state_lock = threading.Lock()

# 1. User Registration & Balance Query
@app.route('/api/register', methods=['POST'])
def register_user():
    data = request.get_json() or {}
    name = data.get('name')
    email = data.get('email')
    password = data.get('password')
    if not name or not email or not password:
        return jsonify({"error": "Name, email, and password required"}), 400

    with state_lock:
        if any(u['email'] == email for u in users_db.values()):
            return jsonify({"error": "User with this email already exists"}), 409
        uid = len(users_db) + 1
        # Initialize with starting bonus balance for testing
        users_db[uid] = {"id": uid, "name": name, "email": email, "password": password, "balance": 100.0}

    return jsonify({"message": "User registered successfully", "user_id": uid, "balance": 100.0}), 201

@app.route('/api/users/<int:user_id>/balance', methods=['GET'])
def get_balance(user_id):
    with state_lock:
        user = users_db.get(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        return jsonify({"user_id": user_id, "balance": user['balance']}), 200

# 2. Atomic P2P Payment with Idempotency & Double-Spending Protection
@app.route('/api/transactions', methods=['POST'])
def create_transaction():
    data = request.get_json() or {}
    idem_key = request.headers.get('Idempotency-Key') or data.get('idempotency_key')
    sender_id = data.get('sender_id')
    receiver_id = data.get('receiver_id')
    amount = data.get('amount')
    note = data.get('note', 'Payment')
    privacy = data.get('privacy', 'PUBLIC').upper()

    if not sender_id or not receiver_id or not amount:
        return jsonify({"error": "sender_id, receiver_id, and amount required"}), 400
    if float(amount) <= 0:
        return jsonify({"error": "Amount must be positive"}), 400
    if sender_id == receiver_id:
        return jsonify({"error": "Cannot send money to yourself"}), 400

    with state_lock:
        # Check idempotency to prevent duplicate charges
        if idem_key and idem_key in idempotency_keys:
            return jsonify(idempotency_keys[idem_key]), 200

        sender = users_db.get(sender_id)
        receiver = users_db.get(receiver_id)
        if not sender or not receiver:
            return jsonify({"error": "Invalid sender or receiver ID"}), 404

        if sender['balance'] < float(amount):
            return jsonify({"error": "Insufficient balance"}), 400

        # Atomic Double-Entry Ledger execution
        sender['balance'] -= float(amount)
        receiver['balance'] += float(amount)

        tx_id = len(transactions_db) + 1
        tx_record = {
            "id": tx_id,
            "sender_id": sender_id,
            "sender_name": sender['name'],
            "receiver_id": receiver_id,
            "receiver_name": receiver['name'],
            "amount": float(amount),
            "note": note,
            "privacy": privacy,
            "timestamp": datetime.utcnow().isoformat()
        }
        transactions_db[tx_id] = tx_record

        res = {"message": "Payment sent successfully", "transaction": tx_record}
        if idem_key:
            idempotency_keys[idem_key] = res

        return jsonify(res), 201

# 3. Social Feed Generation with Privacy Filtering
@app.route('/api/users/<int:user_id>/feed', methods=['GET'])
def get_social_feed(user_id):
    # In production, this checks mutual friendships. Here, we enforce privacy rules:
    # - PRIVATE: Only visible if user_id is sender or receiver.
    # - FRIENDS / PUBLIC: Visible in the social stream.
    feed = []
    with state_lock:
        for tx in reversed(list(transactions_db.values())):
            if tx['privacy'] == 'PRIVATE':
                if tx['sender_id'] == user_id or tx['receiver_id'] == user_id:
                    feed.append(tx)
            else:
                feed.append(tx)

    return jsonify({"feed": feed}), 200

# 4. Likes & Comments Social Endpoints
@app.route('/api/transactions/<int:tx_id>/like', methods=['POST'])
def like_transaction(tx_id):
    data = request.get_json() or {}
    user_id = data.get('user_id', 1)
    with state_lock:
        if tx_id not in transactions_db:
            return jsonify({"error": "Transaction not found"}), 404
        likes_db.setdefault(tx_id, set()).add(user_id)
    return jsonify({"message": "Transaction liked successfully", "likes_count": len(likes_db[tx_id])}), 200

@app.route('/api/transactions/<int:tx_id>/comment', methods=['POST'])
def add_comment(tx_id):
    data = request.get_json() or {}
    user_id = data.get('user_id', 1)
    text = data.get('comment')
    if not text:
        return jsonify({"error": "Comment text required"}), 400

    with state_lock:
        if tx_id not in transactions_db:
            return jsonify({"error": "Transaction not found"}), 404
        comment_entry = {"user_id": user_id, "comment": text, "timestamp": datetime.utcnow().isoformat()}
        comments_db.setdefault(tx_id, []).append(comment_entry)
    return jsonify({"message": "Comment added successfully", "comment": comment_entry}), 201

# 5. Bank Cash-Out (Instant vs Standard)
@app.route('/api/payments/cashout', methods=['POST'])
def cash_out():
    data = request.get_json() or {}
    user_id = data.get('user_id')
    amount = float(data.get('amount', 0))
    transfer_type = data.get('transfer_type', 'standard') # 'instant' or 'standard'

    with state_lock:
        user = users_db.get(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        if user['balance'] < amount:
            return jsonify({"error": "Insufficient balance"}), 400

        fee = (amount * 0.0175) if transfer_type == 'instant' else 0.0
        user['balance'] -= amount
        net_payout = amount - fee

    return jsonify({
        "message": f"{transfer_type.capitalize()} transfer initiated successfully",
        "gross_amount": amount,
        "fee": fee,
        "net_payout": net_payout,
        "eta": "Within 30 minutes" if transfer_type == 'instant' else "1-3 business days"
    }), 200

if __name__ == '__main__':
    app.run(port=5000, debug=True)

