#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <shared_mutex>
#include <chrono>
#include <iomanip>
#include <sstream>
#include <optional>

enum class PrivacyLevel { PUBLIC, FRIENDS_ONLY, PRIVATE };

struct UserAccount {
    int64_t userId;
    std::string username;
    std::string email;
    double balance;
};

struct LedgerTransaction {
    int64_t transactionId;
    int64_t senderId;
    int64_t receiverId;
    double amount;
    std::string note;
    PrivacyLevel privacy;
    std::string timestamp;
};

class VenmoPaymentEngine {
private:
    std::unordered_map<int64_t, UserAccount> users;
    std::unordered_map<int64_t, LedgerTransaction> ledger;
    std::unordered_map<std::string, int64_t> idempotencyStore; // Idempotency-Key -> txId

    mutable std::shared_mutex engineMutex;
    int64_t transactionCounter = 1000;

    std::string getCurrentTimeISO() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::gmtime(&in_time_t), "%Y-%m-%dT%H:%M:%SZ");
        return ss.str();
    }

public:
    void registerUser(int64_t id, const std::string& name, const std::string& email, double initialBalance) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        users[id] = UserAccount{id, name, email, initialBalance};
        std::cout << "[USER CREATED] " << name << " (ID: " << id << ") Balance: $" << initialBalance << "\n";
    }

    // Atomic double-entry transfer with idempotency check and row-level safety
    std::optional<int64_t> transferMoney(const std::string& idempotencyKey, int64_t senderId, int64_t receiverId, double amount, const std::string& note, PrivacyLevel privacy) {
        if (amount <= 0.0 || senderId == receiverId) return std::nullopt;

        std::unique_lock<std::shared_mutex> lock(engineMutex);

        // 1. Idempotency Check
        if (idempotencyStore.find(idempotencyKey) != idempotencyStore.end()) {
            std::cout << "[IDEMPOTENT HIT] Returning existing transaction ID: " << idempotencyStore[idempotencyKey] << "\n";
            return idempotencyStore[idempotencyKey];
        }

        // 2. Account Existence Check
        auto sIt = users.find(senderId);
        auto rIt = users.find(receiverId);
        if (sIt == users.end() || rIt == users.end()) {
            std::cerr << "[ERROR] Sender or Receiver not found!\n";
            return std::nullopt;
        }

        // 3. Balance Constraint (Double-Spending Prevention)
        if (sIt->second.balance < amount) {
            std::cerr << "[REJECTED] Insufficient balance for User " << senderId << "! Available: $" << sIt->second.balance << "\n";
            return std::nullopt;
        }

        // 4. Atomic Execution: Debit Sender, Credit Receiver
        sIt->second.balance -= amount;
        rIt->second.balance += amount;

        int64_t newTxId = ++transactionCounter;
        LedgerTransaction tx{newTxId, senderId, receiverId, amount, note, privacy, getCurrentTimeISO()};
        ledger[newTxId] = tx;
        idempotencyStore[idempotencyKey] = newTxId;

        std::cout << "[PAYMENT SUCCESS] Tx " << newTxId << ": $" << amount << " from User " << senderId << " to User " 
                  << receiverId << " ('" << note << "')\n";
        return newTxId;
    }

    // Feed query with strict privacy filtering
    std::vector<LedgerTransaction> getFeedForUser(int64_t viewerId) const {
        std::shared_lock<std::shared_mutex> lock(engineMutex);
        std::vector<LedgerTransaction> feed;

        for (const auto& [id, tx] : ledger) {
            if (tx.privacy == PrivacyLevel::PRIVATE) {
                // Private transactions are visible ONLY to participants
                if (tx.senderId == viewerId || tx.receiverId == viewerId) {
                    feed.push_back(tx);
                }
            } else {
                // Public and Friends visible
                feed.push_back(tx);
            }
        }
        return feed;
    }

    double getBalance(int64_t userId) const {
        std::shared_lock<std::shared_mutex> lock(engineMutex);
        auto it = users.find(userId);
        return it != users.end() ? it->second.balance : 0.0;
    }
};

int main() {
    VenmoPaymentEngine venmo;

    // Step 1: Onboard users with test funds
    venmo.registerUser(1, "Alice", "alice@example.com", 150.0);
    venmo.registerUser(2, "Bob", "bob@example.com", 50.0);
    venmo.registerUser(3, "Charlie", "charlie@example.com", 20.0);

    std::cout << "\n--- Step 2: Alice sends $40 to Bob with Idempotency Key ---\n";
    std::string key1 = "uuid-1234-abcd";
    auto tx1 = venmo.transferMoney(key1, 1, 2, 40.0, "Dinner & Pizza 🍕", PrivacyLevel::PUBLIC);

    // Retry with identical key (simulating network timeout retry)
    std::cout << "\n--- Step 3: Simulating Network Retry (Same Idempotency Key) ---\n";
    auto tx1_retry = venmo.transferMoney(key1, 1, 2, 40.0, "Dinner & Pizza 🍕", PrivacyLevel::PUBLIC);

    std::cout << "\n--- Step 4: Bob sends $100 to Charlie (Expected to Fail due to balance) ---\n";
    auto tx2 = venmo.transferMoney("uuid-5678-efgh", 2, 3, 100.0, "Concert Ticket", PrivacyLevel::FRIENDS_ONLY);

    std::cout << "\n--- Step 5: Check Updated Balances ---\n";
    std::cout << "Alice Balance: $" << venmo.getBalance(1) << " (Expected 110.0)\n";
    std::cout << "Bob Balance:   $" << venmo.getBalance(2) << " (Expected 90.0)\n";
    std::cout << "Charlie Balance: $" << venmo.getBalance(3) << " (Expected 20.0)\n";

    std::cout << "\n--- Step 6: Generate Feed for Charlie (Privacy Enforcement) ---\n";
    auto feed = venmo.getFeedForUser(3);
    for (const auto& item : feed) {
        std::cout << "Feed Item [Tx " << item.transactionId << "]: User " << item.senderId << " paid User " 
                  << item.receiverId << " | Note: " << item.note << "\n";
    }

    return 0;
}

