from flask import Flask, request, jsonify
from datetime import datetime, timedelta
import jwt
import threading

app = Flask(__name__)
app.config['SECRET_KEY'] = 'pramp_production_secret_key_2026'

# Production in-memory database simulation with concurrency lock
users_db = {}
interviews_db = {}
feedbacks_db = {} # interview_id -> list of feedbacks
questions_db = {
    1: {"question_id": 1, "title": "Binary Search", "difficulty": "Easy", "description": "Implement iterative binary search."},
    2: {"question_id": 2, "title": "Reverse Linked List", "difficulty": "Easy", "description": "Reverse a singly linked list."},
    3: {"question_id": 3, "title": "LRU Cache", "difficulty": "Medium", "description": "Design an LRU Cache with O(1) ops."}
}
likes_db = {}     # interview_id -> set of user_ids
comments_db = {}  # interview_id -> list of comment strings

state_lock = threading.Lock()

# Helper: Generate JWT Token
def generate_token(user_id):
    payload = {'user_id': user_id, 'exp': datetime.utcnow() + timedelta(minutes=60)}
    return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')

# Middleware: JWT Authentication Decorator
def verify_token(func):
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header:
            return jsonify({'message': 'Authorization token is missing!'}), 401
        try:
            token = auth_header.split(' ')[-1]
            payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            kwargs['current_user_id'] = payload['user_id']
            return func(*args, **kwargs)
        except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
            return jsonify({'message': 'Invalid or expired token!'}), 401
    wrapper.__name__ = func.__name__
    return wrapper

# 1. User Registration & Login
@app.route('/api/register', methods=['POST'])
def register_user():
    data = request.get_json() or {}
    username = data.get('username')
    email = data.get('email')
    password = data.get('password')
    if not username or not email or not password:
        return jsonify({'message': 'Missing required fields'}), 400

    with state_lock:
        if any(u['email'] == email for u in users_db.values()):
            return jsonify({'message': 'User already registered with this email'}), 409
        uid = len(users_db) + 1
        users_db[uid] = {'user_id': uid, 'username': username, 'email': email, 'password': password}
    return jsonify({'message': 'User registered successfully!', 'user_id': uid}), 201

@app.route('/api/login', methods=['POST'])
def login_user():
    data = request.get_json() or {}
    email = data.get('email')
    password = data.get('password')
    with state_lock:
        user = next((u for u in users_db.values() if u['email'] == email and u['password'] == password), None)
    if user:
        token = generate_token(user['user_id'])
        return jsonify({'token': token, 'user_id': user['user_id']}), 200
    return jsonify({'message': 'Invalid credentials!'}), 401

@app.route('/api/user/<int:user_id>', methods=['GET'])
@verify_token
def get_user_profile(user_id, current_user_id):
    with state_lock:
        user = users_db.get(user_id)
    if not user:
        return jsonify({'message': 'User not found!'}), 404
    return jsonify({'user_id': user['user_id'], 'username': user['username'], 'email': user['email']}), 200

# 2. Mock Interview Lifecycle
