# 3. Double-Blind Feedback Submission
@app.route('/api/interview/<int:interview_id>/feedback', methods=['POST'])
@verify_token
def submit_feedback(interview_id, current_user_id):
    data = request.get_json() or {}
    feedback_text = data.get('feedback')
    if not feedback_text:
        return jsonify({'message': 'Feedback text is required'}), 400

    with state_lock:
        if interview_id not in interviews_db:
