#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <mutex>
#include <shared_mutex>
#include <chrono>
#include <optional>
#include <sstream>
#include <iomanip>

enum class InterviewStatus { SCHEDULED, IN_PROGRESS, COMPLETED, CANCELLED };

struct UserProfile {
    int64_t userId;
    std::string username;
    std::string email;
    std::string expertiseLanguage;
    bool isAvailable;
};

struct MockInterviewSession {
    int64_t interviewId;
    int64_t intervieweeId;
    int64_t interviewerId;
    int64_t questionId;
    InterviewStatus status;
    std::string scheduledTime;
    std::unordered_set<int64_t> likes;
    std::vector<std::string> comments;
    std::vector<std::pair<int64_t, std::string>> pendingFeedbacks; // reviewerId -> feedbackText
};

class PrampEngine {
private:
    std::unordered_map<int64_t, UserProfile> users;
    std::unordered_map<int64_t, MockInterviewSession> interviews;

    mutable std::shared_mutex engineMutex;
    int64_t interviewCounter = 1000;

    std::string getCurrentTimeISO() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::gmtime(&in_time_t), "%Y-%m-%dT%H:%M:%SZ");
        return ss.str();
    }

public:
    void registerUser(int64_t id, const std::string& name, const std::string& email, const std::string& lang) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        users[id] = UserProfile{id, name, email, lang, true};
        std::cout << "[USER REGISTERED] " << name << " (Language: " << lang << ")\n";
    }

    // Peer-to-peer matchmaking based on language and mutual availability
    std::vector<std::pair<int64_t, int64_t>> matchAvailablePeers() {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        std::vector<std::pair<int64_t, int64_t>> matches;
        std::vector<int64_t> availablePool;

        for (const auto& [id, u] : users) {
            if (u.isAvailable) availablePool.push_back(id);
        }

        for (size_t i = 0; i < availablePool.size(); ++i) {
            for (size_t j = i + 1; j < availablePool.size(); ++j) {
                int64_t u1 = availablePool[i];
                int64_t u2 = availablePool[j];
                if (users[u1].isAvailable && users[u2].isAvailable && 
                    users[u1].expertiseLanguage == users[u2].expertiseLanguage) {
                    users[u1].isAvailable = false;
                    users[u2].isAvailable = false;
                    matches.push_back({u1, u2});
                    break;
                }
            }
        }
        return matches;
    }

    // Start an interview session between matched peers
    int64_t createInterview(int64_t intervieweeId, int64_t interviewerId, int64_t questionId) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        int64_t iId = ++interviewCounter;
        MockInterviewSession session;
        session.interviewId = iId;
        session.intervieweeId = intervieweeId;
        session.interviewerId = interviewerId;
        session.questionId = questionId;
        session.status = InterviewStatus::IN_PROGRESS;
        session.scheduledTime = getCurrentTimeISO();

        interviews[iId] = session;
        std::cout << "[SESSION STARTED] Interview " << iId << " between Candidate " 
                  << intervieweeId << " and Interviewer " << interviewerId << "\n";
        return iId;
    }

    // Double-blind feedback resolution
    void submitFeedback(int64_t interviewId, int64_t reviewerId, const std::string& feedback) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        auto it = interviews.find(interviewId);
        if (it == interviews.end()) return;

        it->second.pendingFeedbacks.push_back({reviewerId, feedback});
        std::cout << "[FEEDBACK RECEIVED] Interview " << interviewId << " from User " << reviewerId << "\n";

        // When both submit, mark session as COMPLETED and unlock reviews
        if (it->second.pendingFeedbacks.size() >= 2) {
            it->second.status = InterviewStatus::COMPLETED;
            std::cout << "[REVIEWS UNLOCKED] Double-blind reviews published for Interview " << interviewId << "!\n";
        }
    }

    void likeInterview(int64_t userId, int64_t interviewId) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        auto it = interviews.find(interviewId);
        if (it != interviews.end()) {
            it->second.likes.insert(userId);
            std::cout << "[LIKED] User " << userId << " liked Interview " << interviewId << "\n";
