#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <queue>
#include <cmath>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <optional>

struct GeoPoint {
    double latitude;
    double longitude;

    double distanceTo(const GeoPoint& other) const {
        constexpr double R = 6371.0; // km
        double dLat = (other.latitude - latitude) * M_PI / 180.0;
        double dLon = (other.longitude - longitude) * M_PI / 180.0;
        double a = std::sin(dLat / 2) * std::sin(dLat / 2) +
                   std::cos(latitude * M_PI / 180.0) * std::cos(other.latitude * M_PI / 180.0) *
                   std::sin(dLon / 2) * std::sin(dLon / 2);
        return R * 2 * std::atan2(std::sqrt(a), std::sqrt(1 - a));
    }
};

struct GraphEdge {
    int64_t toNodeId;
    double distanceKm;
    double currentSpeedKmh;
    std::string streetName;

    double travelTimeHours() const {
        return distanceKm / (currentSpeedKmh > 0 ? currentSpeedKmh : 30.0);
    }
};

struct PlacePOI {
    int64_t placeId;
    std::string name;
    std::string category;
    GeoPoint location;
    double rating;
};

class AppleMapsRoutingEngine {
private:
    // Road Network Graph: NodeId -> List of directed road edges
    std::unordered_map<int64_t, std::vector<GraphEdge>> roadGraph;
    std::unordered_map<int64_t, GeoPoint> nodeCoordinates;
    std::unordered_map<int64_t, PlacePOI> poiCatalog;

    mutable std::shared_mutex graphMutex;

public:
    void addRoadIntersection(int64_t nodeId, double lat, double lon) {
        std::unique_lock<std::shared_mutex> lock(graphMutex);
        nodeCoordinates[nodeId] = {lat, lon};
    }

    void addRoadSegment(int64_t fromNode, int64_t toNode, double distKm, double speedLimit, const std::string& street) {
        std::unique_lock<std::shared_mutex> lock(graphMutex);
        roadGraph[fromNode].push_back(GraphEdge{toNode, distKm, speedLimit, street});
    }

    void updateTrafficSpeed(int64_t fromNode, int64_t toNode, double realTimeSpeed) {
        std::unique_lock<std::shared_mutex> lock(graphMutex);
        if (roadGraph.count(fromNode)) {
            for (auto& edge : roadGraph[fromNode]) {
                if (edge.toNodeId == toNode) {
                    edge.currentSpeedKmh = realTimeSpeed;
                    std::cout << "[TRAFFIC UPDATE] " << edge.streetName << " speed updated to " << realTimeSpeed << " km/h\n";
                    return;
                }
            }
        }
    }

    // Shortest/Fastest Path Navigation using Dijkstra's Algorithm on Road Graph
    std::vector<std::string> calculateNavigationRoute(int64_t startNode, int64_t endNode) {
        std::shared_lock<std::shared_mutex> lock(graphMutex);

        // Min-heap: pair<travelTimeHours, nodeId>
        using QueueElement = std::pair<double, int64_t>;
        std::priority_queue<QueueElement, std::vector<QueueElement>, std::greater<QueueElement>> pq;

        std::unordered_map<int64_t, double> minTimeToNode;
        std::unordered_map<int64_t, std::pair<int64_t, std::string>> previousStep; // curr -> <prevNode, streetName>

        for (const auto& [node, _] : nodeCoordinates) {
            minTimeToNode[node] = 1e9;
        }

        minTimeToNode[startNode] = 0.0;
        pq.push({0.0, startNode});

        while (!pq.empty()) {
            auto [currTime, currNode] = pq.top();
            pq.pop();

            if (currNode == endNode) break;
            if (currTime > minTimeToNode[currNode]) continue;

            if (!roadGraph.count(currNode)) continue;

            for (const auto& edge : roadGraph.at(currNode)) {
                double newTime = currTime + edge.travelTimeHours();
                if (newTime < minTimeToNode[edge.toNodeId]) {
                    minTimeToNode[edge.toNodeId] = newTime;
                    previousStep[edge.toNodeId] = {currNode, edge.streetName};
                    pq.push({newTime, edge.toNodeId});
                }
            }
        }

        std::vector<std::string> instructions;
        int64_t curr = endNode;
        while (curr != startNode && previousStep.count(curr)) {
            auto [prev, street] = previousStep[curr];
            instructions.insert(instructions.begin(), "Drive along " + street);
            curr = prev;
        }
        instructions.push_back("Your destination is on the right");
        return instructions;
    }

    void registerPOI(int64_t id, const std::string& name, const std::string& cat, double lat, double lon, double rating) {
        std::unique_lock<std::shared_mutex> lock(graphMutex);
        poiCatalog[id] = PlacePOI{id, name, cat, {lat, lon}, rating};
    }

    std::vector<PlacePOI> searchNearbyPOIs(const GeoPoint& userLoc, double radiusKm) {
        std::shared_lock<std::shared_mutex> lock(graphMutex);
        std::vector<PlacePOI> results;
        for (const auto& [_, poi] : poiCatalog) {
            if (userLoc.distanceTo(poi.location) <= radiusKm) {
                results.push_back(poi);
            }
        }
        return results;
    }
};

int main() {
    AppleMapsRoutingEngine engine;

    // 1. Setup intersections (Nodes)
    engine.addRoadIntersection(1, 37.7749, -122.4194); // Market St
    engine.addRoadIntersection(2, 37.7833, -122.4167); // 2nd Ave
    engine.addRoadIntersection(3, 37.8083, -122.4094); // Fisherman's Wharf

    // 2. Setup road edges
    engine.addRoadSegment(1, 2, 1.2, 50.0, "Main Street");
    engine.addRoadSegment(2, 3, 3.5, 60.0, "The Embarcadero Highway");

    // 3. Register Places
    engine.registerPOI(101, "Apple Park Visitor Center", "Landmark", 37.3349, -122.0090, 4.9);
    engine.registerPOI(102, "Blue Bottle Coffee", "Coffee", 37.7764, -122.4233, 4.7);

    std::cout << "--- Step 1: Compute Initial Turn-by-Turn Route ---\n";
    auto route = engine.calculateNavigationRoute(1, 3);
    for (size_t i = 0; i < route.size(); ++i) {
        std::cout << "Step " << (i + 1) << ": " << route[i] << "\n";
    }

    // 4. Inject live traffic congestion event
    std::cout << "\n--- Step 2: Traffic Incident Detected ---\n";
    engine.updateTrafficSpeed(1, 2, 15.0); // Traffic drop to 15 km/h on Main St

    // 5. Search nearby coffee shops within 5km radius
    std::cout << "\n--- Step 3: Spatial Search (Coffee near user) ---\n";
    auto nearby = engine.searchNearbyPOIs({37.7749, -122.4194}, 5.0);
    for (const auto& p : nearby) {
        std::cout << "Found POI: " << p.name << " (" << p.category << ") Rating: " << p.rating << "★\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <queue>
#include <mutex>
#include <thread>
#include <chrono>
#include <atomic>
#include <regex>

struct CrawledPageMeta {
    std::string url;
    std::string domain;
    int httpStatusCode;
    size_t sizeBytes;
    std::string pageTitle;
};

class DistributedUrlFrontier {
private:
    std::unordered_set<std::string> visitedUrls; // Bloom Filter in production
    std::queue<std::string> sharedQueue;
    std::unordered_map<std::string, std::chrono::steady_clock::time_point> domainLastAccess;

    std::mutex frontierMutex;
    const std::chrono::milliseconds politenessCooldown{500}; // 500ms per domain delay

    std::string extractDomain(const std::string& url) {
        std::regex domainRegex(R"(https?://([^/]+))");
        std::smatch match;
        if (std::regex_search(url, match, domainRegex) && match.size() > 1) {
            return match[1].str();
        }
        return "unknown_domain";
    }

public:
    void enqueueUrl(const std::string& url) {
        std::lock_guard<std::mutex> lock(frontierMutex);
        if (visitedUrls.find(url) == visitedUrls.end()) {
            visitedUrls.insert(url);
            sharedQueue.push(url);
        }
    }

    bool dequeueUrl(std::string& outUrl) {
        std::lock_guard<std::mutex> lock(frontierMutex);
        if (sharedQueue.empty()) return false;

        std::string candidate = sharedQueue.front();
        std::string domain = extractDomain(candidate);
        auto now = std::chrono::steady_clock::now();

        // Politeness verification: Avoid DDOSing the same domain
        if (domainLastAccess.find(domain) != domainLastAccess.end()) {
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - domainLastAccess[domain]);
            if (elapsed < politenessCooldown) {
                return false; // Yield to ensure politeness gap
            }
        }

        sharedQueue.pop();
        domainLastAccess[domain] = now;
        outUrl = candidate;
        return true;
    }

    size_t getQueueSize() {
        std::lock_guard<std::mutex> lock(frontierMutex);
        return sharedQueue.size();
    }
};

class CrawlerWorkerEngine {
private:
    DistributedUrlFrontier& frontier;
    std::atomic<bool> isRunning{true};
    std::vector<std::thread> workerThreads;

    void workerLoop(int workerId) {
        while (isRunning) {
            std::string url;
            if (frontier.dequeueUrl(url)) {
                // Simulate HTTP fetching and parsing
                std::cout << "[Worker " << workerId << "] Fetching & Parsing: " << url << "\n";
                std::this_thread::sleep_for(std::chrono::milliseconds(50));

                // Simulated discovered outgoing URLs
                if (url == "https://example.com") {
                    frontier.enqueueUrl("https://example.com/about");
                    frontier.enqueueUrl("https://example.com/contact");
                    frontier.enqueueUrl("https://news.ycombinator.com");
                }
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(20));
            }
        }
    }

public:
    CrawlerWorkerEngine(DistributedUrlFrontier& f) : frontier(f) {}

    void start(int numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workerThreads.emplace_back(&CrawlerWorkerEngine::workerLoop, this, i + 1);
        }
    }

    void stop() {
        isRunning = false;
        for (auto& t : workerThreads) {
            if (t.joinable()) t.join();
        }
    }
};

int main() {
    DistributedUrlFrontier frontier;
    frontier.enqueueUrl("https://example.com");

    CrawlerWorkerEngine engine(frontier);
    std::cout << "--- Starting Multi-Threaded Distributed Crawler (192 QPS baseline) ---\n";
    engine.start(4);

    // Run crawler for 1.5 seconds
    std::this_thread::sleep_for(std::chrono::milliseconds(1500));
    engine.stop();

    std::cout << "--- Crawling Batch Completed. Total Remaining URLs in Queue: " 
              << frontier.getQueueSize() << " ---\n";
    return 0;
}

