from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit, join_room, leave_room
from datetime import datetime
import threading

app = Flask(__name__)
app.config['SECRET_KEY'] = 'google_docs_secret_key_2026'
socketio = SocketIO(app, cors_allowed_origins="*")

# Production in-memory state models
users_db = {}
documents_db = {}
collaborators_db = {} # doc_id -> dict(user_id -> role)
comments_db = {}      # doc_id -> list of comments
active_rooms = {}     # doc_id -> set of socket sids

state_lock = threading.Lock()

# Operational Transformation (OT) Helper for Text Insert/Delete
def transform_operation(incoming_op, committed_op):
    # op format: {'type': 'insert'|'delete', 'pos': int, 'text': str, 'base_rev': int}
    transformed = incoming_op.copy()
    if committed_op['type'] == 'insert':
        if incoming_op['pos'] >= committed_op['pos']:
            transformed['pos'] += len(committed_op['text'])
    elif committed_op['type'] == 'delete':
        if incoming_op['pos'] > committed_op['pos']:
            shift = min(incoming_op['pos'] - committed_op['pos'], len(committed_op['text']))
            transformed['pos'] -= shift
    return transformed

# 1. User & Document REST Endpoints
@app.route('/users', methods=['POST'])
def create_user():
    data = request.get_json() or {}
    uid = len(users_db) + 1
    users_db[uid] = {'user_id': uid, 'username': data.get('username'), 'password': data.get('password')}
    return jsonify({'user_id': uid}), 201

@app.route('/documents', methods=['POST'])
def create_document():
    data = request.get_json() or {}
    doc_id = len(documents_db) + 1
    doc = {
        'doc_id': doc_id,
        'title': data.get('title', 'Untitled Document'),
        'content': data.get('content', ''),
        'owner_id': data.get('owner_id', 1),
        'revision': 0,
        'history': [] # Log of committed operations
    }
    documents_db[doc_id] = doc
    collaborators_db[doc_id] = {data.get('owner_id', 1): 'OWNER'}
    return jsonify({'doc_id': doc_id}), 201

@app.route('/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    doc = documents_db.get(doc_id)
    if not doc: return jsonify({'error': 'Document not found'}), 404
    return jsonify(doc), 200

@app.route('/collaboration/<int:doc_id>', methods=['POST'])
def add_collaborator(doc_id):
    data = request.get_json() or {}
    uid = data.get('user_id')
    with state_lock:
        if doc_id not in documents_db or uid not in users_db:
            return jsonify({'error': 'Invalid document or user'}), 404
        collaborators_db[doc_id][uid] = data.get('role', 'EDITOR')
    return jsonify({'message': 'Collaborator added successfully'}), 200

# 2. Real-Time Collaborative WebSockets with OT Engine
@socketio.on('join_document')
def on_join_document(data):
    doc_id = data.get('doc_id')
    user_id = data.get('user_id')
    room = f"doc_{doc_id}"
    join_room(room)
    active_rooms.setdefault(doc_id, set()).add(request.sid)

    doc = documents_db.get(doc_id, {'content': '', 'revision': 0})
    emit('init_document_state', {
        'content': doc['content'],
        'revision': doc['revision'],
        'active_collaborators': len(active_rooms[doc_id])
    })
    emit('collaborator_joined', {'user_id': user_id, 'sid': request.sid}, room=room, include_self=False)

@socketio.on('submit_operation')
def on_submit_operation(data):
    # data: {'doc_id': int, 'user_id': int, 'op': {'type': 'insert', 'pos': int, 'text': 'a', 'base_rev': int}}
    doc_id = data.get('doc_id')
    incoming_op = data.get('op')
    room = f"doc_{doc_id}"

    with state_lock:
        doc = documents_db.get(doc_id)
        if not doc: return

        # OT: Transform incoming op against all committed operations since incoming_op['base_rev']
        base_rev = incoming_op.get('base_rev', doc['revision'])
        for committed_op in doc['history'][base_rev:]:
            incoming_op = transform_operation(incoming_op, committed_op)

        # Apply transformed op to authoritative server document state
        content = list(doc['content'])
        if incoming_op['type'] == 'insert':
            pos = min(incoming_op['pos'], len(content))
            content[pos:pos] = list(incoming_op['text'])
        elif incoming_op['type'] == 'delete':
            pos = incoming_op['pos']
            length = len(incoming_op.get('text', ' '))
            del content[pos:pos + length]

        doc['content'] = ''.join(content)
        doc['revision'] += 1
        incoming_op['server_rev'] = doc['revision']
        doc['history'].append(incoming_op)

        # Acknowledge to sender with official server revision
        emit('op_ack', {'server_rev': doc['revision']})
        # Broadcast transformed op to all other active collaborators in the room
        emit('apply_remote_op', incoming_op, room=room, include_self=False)

@socketio.on('cursor_move')
def on_cursor_move(data):
    # Stream mouse caret tracking without persisting to DB
    room = f"doc_{data.get('doc_id')}"
    emit('collaborator_cursor_updated', data, room=room, include_self=False)

@socketio.on('disconnect')
def on_disconnect():
    for doc_id, sids in active_rooms.items():
        if request.sid in sids:
            sids.remove(request.sid)
            emit('collaborator_left', {'sid': request.sid}, room=f"doc_{doc_id}")

if __name__ == '__main__':
    socketio.run(app, port=5000, debug=True)

