#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <mutex>
#include <memory>
#include <optional>

enum class OpType { INSERT, DELETE };

struct TextOperation {
    OpType type;
    size_t position;
    std::string text;
    int64_t baseRevision;
    int64_t serverRevision;
};

class OperationalTransformationEngine {
public:
    // Pure function: Transform opA against committed opB
    static TextOperation transform(const TextOperation& opA, const TextOperation& opB) {
        TextOperation transformed = opA;
        if (opB.type == OpType::INSERT) {
            if (opA.position >= opB.position) {
                transformed.position += opB.text.length();
            }
        } else if (opB.type == OpType::DELETE) {
            if (opA.position > opB.position) {
                size_t shift = std::min(opA.position - opB.position, opB.text.length());
                transformed.position -= shift;
            }
        }
        return transformed;
    }
};

class GoogleDocsRoomCoordinator {
private:
    int64_t docId;
    std::string content;
    int64_t currentRevision;
    std::vector<TextOperation> operationHistory;
    mutable std::shared_mutex roomMutex;

public:
    GoogleDocsRoomCoordinator(int64_t id, const std::string& initialText)
        : docId(id), content(initialText), currentRevision(0) {}

    // Atomic Operation Submission: Linearizes concurrent edits and guarantees consistency
    TextOperation submitClientOperation(TextOperation incomingOp) {
        std::unique_lock<std::shared_mutex> lock(roomMutex);

        // 1. Transform incoming operation against all newer committed ops
        for (size_t i = incomingOp.baseRevision; i < operationHistory.size(); ++i) {
            incomingOp = OperationalTransformationEngine::transform(incomingOp, operationHistory[i]);
        }

        // 2. Apply transformed operation to memory string state
        if (incomingOp.type == OpType::INSERT) {
            if (incomingOp.position > content.length()) incomingOp.position = content.length();
            content.insert(incomingOp.position, incomingOp.text);
        } else if (incomingOp.type == OpType::DELETE) {
            if (incomingOp.position < content.length()) {
                content.erase(incomingOp.position, incomingOp.text.length());
            }
        }

        // 3. Increment revision and append to immutable log
        currentRevision++;
        incomingOp.serverRevision = currentRevision;
        operationHistory.push_back(incomingOp);

        std::cout << "[DOC " << docId << " REV " << currentRevision << "] Applied '"
                  << (incomingOp.type == OpType::INSERT ? "INSERT " : "DELETE ")
                  << incomingOp.text << "' at pos " << incomingOp.position
                  << " | Current Content: '" << content << "'\n";

        return incomingOp;
    }

    std::string getCurrentContent() const {
        std::shared_lock<std::shared_mutex> lock(roomMutex);
        return content;
    }

    int64_t getRevision() const {
        std::shared_lock<std::shared_mutex> lock(roomMutex);
        return currentRevision;
    }
};

int main() {
    // Document initialized with text "CAT"
    GoogleDocsRoomCoordinator doc(101, "CAT");
    std::cout << "Initial State: '" << doc.getCurrentContent() << "' (Rev 0)\n\n";

    // Simulating Concurrent Edits at Rev 0:
    // User 1 wants to prepend 'B' at pos 0 ("BCAT")
    TextOperation opUser1{OpType::INSERT, 0, "B", 0, 0};

    // User 2 concurrently wants to append 'S' at pos 3 ("CATS") based on Rev 0
    TextOperation opUser2{OpType::INSERT, 3, "S", 0, 0};

    std::cout << "--- Step 1: User 1 edit arrives first at server ---\n";
    doc.submitClientOperation(opUser1);

    std::cout << "\n--- Step 2: User 2 concurrent edit arrives with outdated Base Rev 0 ---\n";
    // Coordinator transforms opUser2 against opUser1 -> position becomes 4 instead of 3
    doc.submitClientOperation(opUser2);

    std::cout << "\nFinal Converged Document Content: '" << doc.getCurrentContent() << "' (Expected 'BCATS')\n";
    return 0;
}

