    stage: str = "PROSPECT"
    closing_date: Optional[str] = None
    description: Optional[str] = ""

# Multi-Tenant Context Dependency
def verify_tenant(x_tenant_id: int = Header(...)):
    with state_lock:
        if x_tenant_id not in tenants_db:
            raise HTTPException(status_code=403, detail="Invalid or unauthorized Tenant ID")
    return x_tenant_id

# 1. Tenant & User Setup
@app.post("/api/v1/auth/register-tenant", status_code=201)
