        t_id = len(tenants_db) + 1
        tenants_db[t_id] = {"tenant_id": t_id, "company_name": company_name, "domain": domain}
        u_id = len(users_db) + 1
        users_db[u_id] = {"user_id": u_id, "tenant_id": t_id, "email": admin_email, "role": "ADMIN"}
    return {"status": "success", "tenant_id": t_id, "admin_user_id": u_id}

# 2. Leads Management with Custom Properties & Scoring
@app.post("/api/v1/leads", status_code=201)
def create_lead(lead: LeadCreateSchema, tenant_id: int = Depends(verify_tenant)):
    with state_lock:
        lead_id = len(leads_db) + 1
        # Baseline behavioral score
        initial_score = 15 if lead.source == "WEBSITE" else 5
        lead_record = {
            "lead_id": lead_id,
            "tenant_id": tenant_id,
            "name": lead.name,
            "email": lead.email,
            "phone": lead.phone,
            "company": lead.company,
