            "source": lead.source,
            "score": initial_score,
            "custom_properties": lead.custom_properties,
            "created_at": datetime.utcnow().isoformat()
        }
        leads_db[lead_id] = lead_record
    return {"status": "success", "message": "Lead created successfully", "lead": lead_record}

@app.get("/api/v1/leads/{lead_id}")
def get_lead(lead_id: int, tenant_id: int = Depends(verify_tenant)):
    with state_lock:
        lead = leads_db.get(lead_id)
        # Ensure strict tenant boundary isolation
        if not lead or lead["tenant_id"] != tenant_id:
            raise HTTPException(status_code=404, detail="Lead not found")
    return lead

@app.patch("/api/v1/leads/{lead_id}/score")
def update_lead_score(lead_id: int, points: int, tenant_id: int = Depends(verify_tenant)):
    with state_lock:
        lead = leads_db.get(lead_id)
        if not lead or lead["tenant_id"] != tenant_id:
            raise HTTPException(status_code=404, detail="Lead not found")
        lead["score"] += points
        if lead["score"] >= 80 and lead["status"] == "NEW":
            lead["status"] = "QUALIFIED" # Automated stage transition trigger
    return {"lead_id": lead_id, "new_score": lead["score"], "status": lead["status"]}

# 3. Sales Pipeline Deals
@app.post("/api/v1/deals", status_code=201)
def create_deal(deal: DealCreateSchema, tenant_id: int = Depends(verify_tenant)):
    with state_lock:
