            "stage": deal.stage,
            "closing_date": deal.closing_date,
            "description": deal.description,
            "created_at": datetime.utcnow().isoformat()
        }
        deals_db[deal_id] = deal_record
    return {"status": "success", "deal": deal_record}

# 4. Pipeline Analytics & Forecast
@app.get("/api/v1/reports/pipeline")
def get_pipeline_summary(tenant_id: int = Depends(verify_tenant)):
