#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <mutex>
#include <memory>
#include <chrono>
#include <optional>
#include <iomanip>

enum class LeadStatus { NEW, QUALIFIED, LOST, WON };
enum class DealStage { PROSPECT, QUALIFIED, NEGOTIATION, CLOSED_WON, CLOSED_LOST };

struct LeadRecord {
    int64_t leadId;
    int64_t tenantId;
    std::string name;
    std::string email;
    std::string company;
    LeadStatus status;
    int score;
    std::unordered_map<std::string, std::string> customProperties; // EAV dynamic fields
};

struct DealOpportunity {
    int64_t dealId;
    int64_t tenantId;
    std::string dealName;
    double amount;
    DealStage stage;
};

class HubSpotCRMEngine {
private:
    // Multi-tenant partitioned data structures
    std::unordered_map<int64_t, std::unordered_map<int64_t, LeadRecord>> tenantLeads; // tenantId -> (leadId -> Lead)
    std::unordered_map<int64_t, std::unordered_map<int64_t, DealOpportunity>> tenantDeals; // tenantId -> (dealId -> Deal)

    mutable std::shared_mutex crmMutex;
    int64_t leadIdSequence = 1000;
    int64_t dealIdSequence = 5000;

public:
    // Thread-safe Lead Creation with dynamic EAV custom attributes
    int64_t createLead(int64_t tenantId, const std::string& name, const std::string& email, 
                       const std::string& company, const std::unordered_map<std::string, std::string>& customFields) {
        std::unique_lock<std::shared_mutex> lock(crmMutex);
        int64_t newId = ++leadIdSequence;

        LeadRecord record{
            newId, tenantId, name, email, company, LeadStatus::NEW, 10, customFields
        };
        tenantLeads[tenantId][newId] = record;
        std::cout << "[LEAD CREATED] Tenant " << tenantId << " | Lead " << newId << " (" << name << ")\n";
        return newId;
    }

    // Behavioral Lead Scoring update (Triggers stage upgrade)
    void updateEngagementScore(int64_t tenantId, int64_t leadId, int deltaPoints) {
        std::unique_lock<std::shared_mutex> lock(crmMutex);
        if (tenantLeads.count(tenantId) && tenantLeads[tenantId].count(leadId)) {
            auto& lead = tenantLeads[tenantId][leadId];
            lead.score += deltaPoints;
            std::cout << "[SCORE UPDATED] Lead " << leadId << " new score: " << lead.score;

            if (lead.score >= 50 && lead.status == LeadStatus::NEW) {
                lead.status = LeadStatus::QUALIFIED;
                std::cout << " -> [AUTO-QUALIFIED TO MQL]";
            }
            std::cout << "\n";
        }
    }

    // Create sales pipeline deal
    int64_t createDeal(int64_t tenantId, const std::string& name, double amount, DealStage stage) {
        std::unique_lock<std::shared_mutex> lock(crmMutex);
        int64_t newId = ++dealIdSequence;
        DealOpportunity deal{newId, tenantId, name, amount, stage};
        tenantDeals[tenantId][newId] = deal;
        std::cout << "[DEAL LOGGED] Deal " << newId << " ('" << name << "') Amount: $" << amount << "\n";
        return newId;
    }

    // Fast OLAP pipeline aggregation per tenant
    double calculatePipelineTotal(int64_t tenantId) const {
        std::shared_lock<std::shared_mutex> lock(crmMutex);
        double total = 0.0;
        if (tenantDeals.count(tenantId)) {
            for (const auto& [_, deal] : tenantDeals.at(tenantId)) {
                total += deal.amount;
            }
        }
        return total;
    }
};

int main() {
    HubSpotCRMEngine crm;
    int64_t acmeTenantId = 101;

    std::cout << "--- Step 1: Ingesting Inbound Lead with Custom Properties ---\n";
    std::unordered_map<std::string, std::string> customFields = {
        {"budget", "$50,000"},
        {"industry", "Fintech"},
        {"preferred_cloud", "AWS"}
    };
    int64_t leadId = crm.createLead(acmeTenantId, "Alice Miller", "alice@fintech.io", "Fintech Solutions", customFields);

    std::cout << "\n--- Step 2: Processing Behavioral Engagement Events ---\n";
    crm.updateEngagementScore(acmeTenantId, leadId, 25); // Pricing page visit
    crm.updateEngagementScore(acmeTenantId, leadId, 20); // Webinar attendance (Crosses 50 -> Auto-Qualified)

    std::cout << "\n--- Step 3: Logging Pipeline Deals & Calculating Forecast ---\n";
    crm.createDeal(acmeTenantId, "Fintech Enterprise License", 45000.0, DealStage::NEGOTIATION);
    crm.createDeal(acmeTenantId, "Custom Integration Add-on", 15000.0, DealStage::PROSPECT);

    std::cout << "Total Active Pipeline for Tenant " << acmeTenantId << ": $" 
              << std::fixed << std::setprecision(2) << crm.calculatePipelineTotal(acmeTenantId) << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <mutex>
#include <chrono>
#include <iomanip>
#include <sstream>
#include <optional>

enum class WorkflowType { SEQUENTIAL, PARALLEL };
enum class EnvelopeStatus { DRAFT, IN_PROGRESS, COMPLETED, VOIDED };
enum class RecipientStatus { WAITING, SIGNED };

struct SignerRecipient {
    int64_t recipientId;
    std::string name;
    std::string email;
    int routingOrder;
    RecipientStatus status;
};

struct AuditEvent {
    std::string action;
    std::string actorEmail;
    std::string timestamp;
};

struct EnvelopeTransaction {
    int64_t envelopeId;
    std::string title;
    WorkflowType workflow;
    EnvelopeStatus status;
    int currentRoutingOrder;
    std::vector<SignerRecipient> recipients;
    std::vector<AuditEvent> auditLog;
};

class DocuSignEngine {
private:
    std::unordered_map<int64_t, EnvelopeTransaction> envelopes;
    mutable std::shared_mutex engineMutex;
    int64_t envelopeCounter = 9000;

    std::string getCurrentTimeISO() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::gmtime(&in_time_t), "%Y-%m-%dT%H:%M:%SZ");
        return ss.str();
    }

public:
    // Thread-safe envelope transaction creation
    int64_t createEnvelope(const std::string& title, WorkflowType workflow, const std::vector<std::pair<std::string, std::string>>& signers) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        int64_t envId = ++envelopeCounter;

        EnvelopeTransaction env;
        env.envelopeId = envId;
        env.title = title;
        env.workflow = workflow;
        env.status = EnvelopeStatus::IN_PROGRESS;
        env.currentRoutingOrder = 1;

        for (size_t i = 0; i < signers.size(); ++i) {
            env.recipients.push_back({
                static_cast<int64_t>(i + 1),
                signers[i].first,
                signers[i].second,
                static_cast<int>(i + 1),
                RecipientStatus::WAITING
            });
        }

        env.auditLog.push_back({"ENVELOPE_CREATED", "creator@system.com", getCurrentTimeISO()});
        envelopes[envId] = env;

        std::cout << "[ENVELOPE CREATED] ID: " << envId << " | '" << title << "' with " << signers.size() << " signers\n";
        return envId;
    }

    // Atomic signing with sequential workflow verification
    bool signDocument(int64_t envelopeId, const std::string& signerEmail, const std::string& digitalSigHash) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        auto it = envelopes.find(envelopeId);
        if (it == envelopes.end() || it->second.status != EnvelopeStatus::IN_PROGRESS) {
            std::cerr << "[ERROR] Envelope not found or not in progress!\n";
            return false;
        }

        auto& env = it->second;
        SignerRecipient* targetSigner = nullptr;

        for (auto& r : env.recipients) {
            if (r.email == signerEmail) {
                targetSigner = &r;
                break;
            }
        }

        if (!targetSigner) {
            std::cerr << "[ERROR] Signer " << signerEmail << " not assigned to this envelope!\n";
            return false;
        }

        // Sequential workflow order validation
        if (env.workflow == WorkflowType::SEQUENTIAL && targetSigner->routingOrder != env.currentRoutingOrder) {
            std::cerr << "[REJECTED] Order constraint: Waiting for Order " << env.currentRoutingOrder 
                      << ". Signer is Order " << targetSigner->routingOrder << "\n";
            return false;
        }

        // Apply signature
        targetSigner->status = RecipientStatus::SIGNED;
        env.auditLog.push_back({"SIGNED", signerEmail, getCurrentTimeISO()});
        std::cout << "[SUCCESS] Signer " << signerEmail << " executed signature with Hash: " << digitalSigHash << "\n";

        // Advance state machine
        bool allSigned = true;
        for (const auto& r : env.recipients) {
            if (r.status != RecipientStatus::SIGNED) {
                allSigned = false;
                break;
            }
        }

        if (allSigned) {
            env.status = EnvelopeStatus::COMPLETED;
            env.auditLog.push_back({"ENVELOPE_SEALED", "SYSTEM", getCurrentTimeISO()});
            std::cout << "[COMPLETED] All parties signed. Envelope " << envelopeId << " sealed permanently!\n";
        } else if (env.workflow == WorkflowType::SEQUENTIAL) {
            env.currentRoutingOrder++;
            std::cout << "[WORKFLOW ADVANCED] Next required routing order: " << env.currentRoutingOrder << "\n";
        }

        return true;
    }

    void printAuditTrail(int64_t envelopeId) const {
        std::shared_lock<std::shared_mutex> lock(engineMutex);
        auto it = envelopes.find(envelopeId);
        if (it == envelopes.end()) return;

        std::cout << "\n--- Audit Trail for Envelope " << envelopeId << " ---\n";
        for (const auto& event : it->second.auditLog) {
            std::cout << "[" << event.timestamp << "] Action: " << event.action << " by " << event.actorEmail << "\n";
        }
    }
};

int main() {
    DocuSignEngine engine;

    // 1. Create a Sequential 2-party NDA Agreement
    std::vector<std::pair<std::string, std::string>> signers = {
        {"Alice Green", "alice@vendor.com"}, // Order 1
        {"Bob Smith", "bob@enterprise.com"}  // Order 2
    };
    int64_t envId = engine.createEnvelope("Vendor NDA 2026", WorkflowType::SEQUENTIAL, signers);

    std::cout << "\n--- Step 2: Bob tries to sign prematurely (Expected to fail) ---\n";
    engine.signDocument(envId, "bob@enterprise.com", "hash_bob_sig_abc");

    std::cout << "\n--- Step 3: Alice signs first (Order 1) ---\n";
    engine.signDocument(envId, "alice@vendor.com", "hash_alice_sig_123");

    std::cout << "\n--- Step 4: Bob signs next (Order 2) ---\n";
    engine.signDocument(envId, "bob@enterprise.com", "hash_bob_sig_abc");

    // 5. Inspect immutable audit certificate trail
    engine.printAuditTrail(envId);

    return 0;
}

