from flask import Flask, request, jsonify
from datetime import datetime
import hashlib
import threading

app = Flask(__name__)

# In-memory storage mock with thread-safety
users_db = {}
likes_db = {}       # swiper_id -> set of swiped_ids (simulates Redis Sets)
matches_db = {}     # match_id -> dict
messages_db = {}    # match_id -> list of messages
sessions_db = {}

state_lock = threading.Lock()

# Helper: Password Hashing
def hash_pwd(pwd):
    return hashlib.sha256(pwd.encode('utf-8')).hexdigest()

# 1. User Profile & Auth Endpoints
@app.route('/signup', methods=['POST'])
def signup():
    data = request.get_json() or {}
    username = data.get('username')
    password = data.get('password')
    if not username or not password:
        return jsonify({'error': 'Missing credentials'}), 400

    with state_lock:
        if username in users_db:
            return jsonify({'error': 'Username already exists'}), 409
        u_id = len(users_db) + 1
        users_db[username] = {
            'user_id': u_id,
            'username': username,
            'password': hash_pwd(password),
            'age': data.get('age', 25),
            'bio': data.get('bio', 'Hello there!'),
            'photos': []
        }
    return jsonify({'result': True, 'user_id': u_id}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json() or {}
    username = data.get('username')
    password = data.get('password')
    with state_lock:
        user = users_db.get(username)
        if user and user['password'] == hash_pwd(password):
            token = f"token_for_{user['user_id']}"
            sessions_db[token] = user['user_id']
            return jsonify({'result': True, 'session_token': token}), 200
    return jsonify({'result': False, 'message': 'Invalid credentials'}), 401

# 2. Recommendations API
@app.route('/recommendations/<int:user_id>', methods=['GET'])
def get_recommendations(user_id):
    # Returns candidate profiles excluding current user and already swiped profiles
    with state_lock:
        already_swiped = likes_db.get(user_id, set())
        candidates = [
            u for u in users_db.values()
            if u['user_id'] != user_id and u['user_id'] not in already_swiped
        ]
    return jsonify({'recommendations': candidates}), 200

# 3. Swipe & Instant Match Execution
@app.route('/swipe', methods=['POST'])
def execute_swipe():
    data = request.get_json() or {}
    swiper_id = data.get('swiper_id')
    swiped_id = data.get('swiped_id')
    action = data.get('action', 'LIKE').upper() # 'LIKE' or 'PASS'

    if not swiper_id or not swiped_id:
        return jsonify({'error': 'Missing swiper_id or swiped_id'}), 400

    is_match = False
    match_payload = None

    with state_lock:
        if action == 'LIKE':
            # Record like in swiper's set
            likes_db.setdefault(swiper_id, set()).add(swiped_id)

            # Reciprocal check: Did swiped_id already like swiper_id?
            if swiper_id in likes_db.get(swiped_id, set()):
                is_match = True
                m_id = f"match_{min(swiper_id, swiped_id)}_{max(swiper_id, swiped_id)}"
                match_record = {
                    'match_id': m_id,
                    'user1_id': min(swiper_id, swiped_id),
                    'user2_id': max(swiper_id, swiped_id),
                    'timestamp': datetime.utcnow().isoformat()
                }
                matches_db[m_id] = match_record
                match_payload = match_record

    return jsonify({
        'is_match': is_match,
        'match': match_payload,
        'message': "It's a Match!" if is_match else f"Swiped {action}"
    }), 200

# 4. Matches & Messaging Endpoints
@app.route('/matches/<int:user_id>', methods=['GET'])
def get_user_matches(user_id):
    with state_lock:
        user_matches = [
            m for m in matches_db.values()
            if m['user1_id'] == user_id or m['user2_id'] == user_id
        ]
    return jsonify({'matches': user_matches}), 200

@app.route('/messages', methods=['POST'])
def send_message():
    data = request.get_json() or {}
    match_id = data.get('match_id')
    sender_id = data.get('sender_id')
    content = data.get('content')

    with state_lock:
        if match_id not in matches_db:
            return jsonify({'error': 'Match does not exist or has been unmatched'}), 404

        match = matches_db[match_id]
        if sender_id not in (match['user1_id'], match['user2_id']):
            return jsonify({'error': 'Sender is not a participant in this match'}), 403

        msg = {
            'message_id': len(messages_db.get(match_id, [])) + 1,
            'sender_id': sender_id,
            'content': content,
            'timestamp': datetime.utcnow().isoformat()
        }
        messages_db.setdefault(match_id, []).append(msg)

    return jsonify({'message': 'Message sent successfully', 'data': msg}), 201

if __name__ == '__main__':
    app.run(port=5000, debug=True)

