public:
    void registerUser(int64_t id, const std::string& name, int age, const std::string& bio, double lat, double lon) {
        std::unique_lock<std::shared_mutex> lock(engineMutex);
        users[id] = UserProfile{id, name, age, bio, lat, lon};
        std::cout << "[USER REGISTERED] " << name << " (ID: " << id << ")\n";
    }

    // Atomic Swipe Processing with Instant Reciprocal Match Detection
    std::optional<MatchRecord> processSwipe(int64_t swiperId, int64_t swipedId, SwipeAction action) {
        if (swiperId == swipedId) return std::nullopt;

        std::unique_lock<std::shared_mutex> lock(engineMutex);

        if (action == SwipeAction::PASS) {
            std::cout << "[SWIPE PASS] User " << swiperId << " passed on User " << swipedId << "\n";
            return std::nullopt;
        }

        // Record Like
        likesMap[swiperId].insert(swipedId);
        std::cout << "[SWIPE LIKE] User " << swiperId << " liked User " << swipedId << "\n";

        // Reciprocal Check: Did swipedId already like swiperId?
        auto it = likesMap.find(swipedId);
        if (it != likesMap.end() && it->second.count(swiperId)) {
            // Mutual Match Detected!
            std::string matchKey = makeMatchKey(swiperId, swipedId);
            MatchRecord match{
                matchKey,
                std::min(swiperId, swipedId),
                std::max(swiperId, swipedId),
                getCurrentTimeISO()
            };
            matchesMap[matchKey] = match;

            std::cout << "==============================================\n";
            std::cout << "🔥 IT'S A MATCH! " << users[swiperId].name << " <---> " 
                      << users[swipedId].name << " (Match ID: " << matchKey << ")\n";
            std::cout << "==============================================\n";
            return match;
        }

        return std::nullopt;
    }

    std::vector<UserProfile> getRecommendations(int64_t userId) const {
        std::shared_lock<std::shared_mutex> lock(engineMutex);
        std::vector<UserProfile> deck;

        auto it = likesMap.find(userId);
        const std::unordered_set<int64_t>& alreadyLiked = (it != likesMap.end()) ? it->second : std::unordered_set<int64_t>{};

        for (const auto& [id, profile] : users) {
            if (id != userId && !alreadyLiked.count(id)) {
                deck.push_back(profile);
            }
        }
        return deck;
    }
};

