    // Step 1: Onboard users
    tinder.registerUser(1, "Alice", 24, "Loves hiking & dogs 🐕", 37.7749, -122.4194);
    tinder.registerUser(2, "Bob", 26, "Coffee addict & musician ☕🎸", 37.7833, -122.4167);
    tinder.registerUser(3, "Charlie", 25, "Tech nerd & foodie 🍕", 37.7933, -122.4067);

    std::cout << "\n--- Step 2: Alice swipes Right on Bob ---\n";
