from flask import Flask, request, jsonify
from datetime import datetime
import uuid
import threading

app = Flask(__name__)

# Production in-memory database simulation with concurrency thread-safety
users_db = {}
wallets_db = {}
transactions_db = {}
tokens_db = {
    'ETH': {'name': 'Ethereum', 'decimals': 18, 'address': None, 'usd_price': 2800.0},
    'USDC': {'name': 'USD Coin', 'decimals': 6, 'address': '0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48', 'usd_price': 1.0}
}
feed_db = {}

state_lock = threading.Lock()

# 1. User Registration & Auth
@app.route('/api/v1/users/register', methods=['POST'])
def register_user():
    data = request.get_json() or {}
    username = data.get('username')
    email = data.get('email')
    password = data.get('password')

    if not email or not password:
        return jsonify({'error': 'Email and password required'}), 400

    with state_lock:
        if any(u['email'] == email for u in users_db.values()):
            return jsonify({'error': 'Email already exists'}), 409
        uid = str(uuid.uuid4())[:8]
        users_db[uid] = {'user_id': uid, 'username': username, 'email': email, 'password': password}

    return jsonify({'message': 'User registered successfully', 'user_id': uid}), 201

# 2. Wallet Multi-Currency Balance Management
@app.route('/api/v1/wallets/create', methods=['POST'])
def create_wallet():
    data = request.get_json() or {}
    user_id = data.get('user_id')
    address = data.get('public_address', f"0x{uuid.uuid4().hex[:40]}")

    with state_lock:
        if user_id not in users_db:
            return jsonify({'error': 'User not found'}), 404
        wid = f"wal_{len(wallets_db) + 1}"
        wallets_db[wid] = {
            'wallet_id': wid,
            'user_id': user_id,
            'address': address,
            'balances': {'ETH': 2.0, 'USDC': 500.0} # Seeded funds for testing
        }
    return jsonify({'message': 'Wallet registered successfully', 'wallet': wallets_db[wid]}), 201

@app.route('/api/v1/wallets/<wallet_id>/balances', methods=['GET'])
def get_balances(wallet_id):
    with state_lock:
        wallet = wallets_db.get(wallet_id)
        if not wallet:
            return jsonify({'error': 'Wallet not found'}), 404

        assets = []
        total_usd = 0.0
        for symbol, balance in wallet['balances'].items():
            price = tokens_db.get(symbol, {}).get('usd_price', 0.0)
            val = balance * price
            total_usd += val
            assets.append({'symbol': symbol, 'balance': balance, 'usd_price': price, 'usd_value': val})

    return jsonify({'wallet_id': wallet_id, 'total_usd': total_usd, 'assets': assets}), 200

# 3. Off-Chain Transaction Broadcast (Signed Raw Execution)
@app.route('/api/v1/transactions/broadcast', methods=['POST'])
def broadcast_tx():
    data = request.get_json() or {}
    sender_wid = data.get('sender_wallet_id')
    recipient_wid = data.get('recipient_wallet_id')
    symbol = data.get('token_symbol', 'ETH')
    amount = float(data.get('amount', 0))

    if amount <= 0:
        return jsonify({'error': 'Invalid amount'}), 400

    with state_lock:
        sender = wallets_db.get(sender_wid)
        recipient = wallets_db.get(recipient_wid)
        if not sender or not recipient:
            return jsonify({'error': 'Invalid wallet ID'}), 404

        if sender['balances'].get(symbol, 0) < amount:
            return jsonify({'error': 'Insufficient balance for transfer'}), 400

        # Atomic transfer execution
        sender['balances'][symbol] -= amount
        recipient['balances'][symbol] = recipient['balances'].get(symbol, 0) + amount

        tx_hash = f"0x{uuid.uuid4().hex}"
        tx_record = {
            'tx_hash': tx_hash,
            'sender_address': sender['address'],
            'recipient_address': recipient['address'],
            'token': symbol,
            'amount': amount,
            'status': 'CONFIRMED',
            'timestamp': datetime.utcnow().isoformat()
        }
        transactions_db[tx_hash] = tx_record

    return jsonify({'message': 'Transaction confirmed on blockchain', 'tx': tx_record}), 201

# 4. Token Swap Aggregator Logic
@app.route('/api/v1/swap/execute', methods=['POST'])
def execute_swap():
    data = request.get_json() or {}
    wallet_id = data.get('wallet_id')
    from_token = data.get('from_token')
    to_token = data.get('to_token')
    amount_in = float(data.get('amount_in', 0))

    with state_lock:
        wallet = wallets_db.get(wallet_id)
        if not wallet:
            return jsonify({'error': 'Wallet not found'}), 404

        if from_token not in tokens_db or to_token not in tokens_db:
            return jsonify({'error': 'Unsupported token for swap'}), 400

        if wallet['balances'].get(from_token, 0) < amount_in:
            return jsonify({'error': 'Insufficient token balance'}), 400

        # Calculate exchange rate based on price ratio
        price_in = tokens_db[from_token]['usd_price']
        price_out = tokens_db[to_token]['usd_price']
        amount_out = (amount_in * price_in) / price_out

        wallet['balances'][from_token] -= amount_in
        wallet['balances'][to_token] = wallet['balances'].get(to_token, 0) + amount_out

    return jsonify({
        'message': 'Token swap successful',
        'swapped_in': f"{amount_in} {from_token}",
        'received_out': f"{round(amount_out, 4)} {to_token}",
        'rate': price_in / price_out
    }), 200

if __name__ == '__main__':
    app.run(port=5000, debug=True)

