#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <mutex>
#include <iomanip>
#include <sstream>
#include <chrono>
#include <optional>

struct CryptoToken {
    std::string symbol;
    std::string name;
    double usdPrice;
    int decimals;
};

struct BlockchainTransaction {
    std::string txHash;
    std::string fromAddress;
    std::string toAddress;
    std::string tokenSymbol;
    double amount;
    std::string status;
    std::string timestamp;
};

class CoinbaseWalletEngine {
private:
    // Address -> (TokenSymbol -> Balance)
    std::unordered_map<std::string, std::unordered_map<std::string, double>> walletBalances;
    std::unordered_map<std::string, CryptoToken> tokenCatalog;
    std::unordered_map<std::string, BlockchainTransaction> ledger;

    mutable std::shared_mutex walletMutex;
    int64_t txCounter = 1000;

    std::string getCurrentTimeISO() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::gmtime(&in_time_t), "%Y-%m-%dT%H:%M:%SZ");
        return ss.str();
    }

public:
    CoinbaseWalletEngine() {
        tokenCatalog["ETH"] = {"ETH", "Ethereum", 2800.0, 18};
        tokenCatalog["BTC"] = {"BTC", "Bitcoin", 65000.0, 8};
        tokenCatalog["USDC"] = {"USDC", "USD Coin", 1.0, 6};
    }

    void registerWallet(const std::string& address, const std::string& symbol, double initialBalance) {
        std::unique_lock<std::shared_mutex> lock(walletMutex);
        walletBalances[address][symbol] = initialBalance;
        std::cout << "[WALLET INITIALIZED] " << address << " | " << initialBalance << " " << symbol << "\n";
    }

    // Atomic on-chain transaction execution
    std::optional<std::string> sendTransaction(const std::string& from, const std::string& to, const std::string& symbol, double amount) {
        if (amount <= 0.0 || from == to) return std::nullopt;

        std::unique_lock<std::shared_mutex> lock(walletMutex);
        if (!tokenCatalog.count(symbol)) {
            std::cerr << "[ERROR] Unsupported token " << symbol << "\n";
            return std::nullopt;
        }

        auto& senderAssets = walletBalances[from];
        if (senderAssets[symbol] < amount) {
            std::cerr << "[REJECTED] Insufficient balance for " << from << " (Available: " << senderAssets[symbol] << ")\n";
            return std::nullopt;
        }

        // Debit & Credit
        senderAssets[symbol] -= amount;
        walletBalances[to][symbol] += amount;

        std::string txHash = "0x" + std::to_string(++txCounter) + "abcdef99887766";
        BlockchainTransaction tx{txHash, from, to, symbol, amount, "CONFIRMED", getCurrentTimeISO()};
        ledger[txHash] = tx;

        std::cout << "[TX CONFIRMED] Hash: " << txHash << " | Transferred " << amount << " " << symbol 
                  << " from " << from << " -> " << to << "\n";
        return txHash;
    }

    // Decentralized In-Wallet Token Swapping
    bool swapTokens(const std::string& address, const std::string& fromToken, const std::string& toToken, double amountIn) {
        std::unique_lock<std::shared_mutex> lock(walletMutex);
        if (!tokenCatalog.count(fromToken) || !tokenCatalog.count(toToken)) return false;

        auto& assets = walletBalances[address];
        if (assets[fromToken] < amountIn) {
            std::cerr << "[SWAP REJECTED] Insufficient " << fromToken << " for swap!\n";
            return false;
        }

        double priceIn = tokenCatalog[fromToken].usdPrice;
        double priceOut = tokenCatalog[toToken].usdPrice;
        double amountOut = (amountIn * priceIn) / priceOut;

        assets[fromToken] -= amountIn;
        assets[toToken] += amountOut;

        std::cout << "[SWAP EXECUTED] " << address << " swapped " << amountIn << " " << fromToken 
                  << " -> " << amountOut << " " << toToken << " (USD Value: $" << (amountIn * priceIn) << ")\n";
        return true;
    }

    double getBalance(const std::string& address, const std::string& symbol) const {
        std::shared_lock<std::shared_mutex> lock(walletMutex);
        if (walletBalances.count(address) && walletBalances.at(address).count(symbol)) {
            return walletBalances.at(address).at(symbol);
        }
        return 0.0;
    }
};

int main() {
    CoinbaseWalletEngine engine;

    std::string alice = "0xAlice1111111111111111111111111111111111";
    std::string bob   = "0xBob222222222222222222222222222222222222";

    std::cout << "--- Step 1: Initializing Wallets with Test Funds ---\n";
    engine.registerWallet(alice, "ETH", 5.0);
    engine.registerWallet(alice, "USDC", 1000.0);
    engine.registerWallet(bob, "ETH", 0.5);

    std::cout << "\n--- Step 2: Alice sends 1.5 ETH to Bob ---\n";
    engine.sendTransaction(alice, bob, "ETH", 1.5);

    std::cout << "\n--- Step 3: Alice swaps 1.0 ETH for USDC via DEX Router ---\n";
    engine.swapTokens(alice, "ETH", "USDC", 1.0);

    std::cout << "\n--- Step 4: Final Wallet Balance Audit ---\n";
    std::cout << "Alice ETH Balance:  " << engine.getBalance(alice, "ETH") << " (Expected 2.5)\n";
    std::cout << "Alice USDC Balance: " << engine.getBalance(alice, "USDC") << " (Expected 3800.0)\n";
    std::cout << "Bob ETH Balance:    " << engine.getBalance(bob, "ETH") << " (Expected 2.0)\n";

    return 0;
}

