import java.util.concurrent.ConcurrentHashMap;

class FlightOption {
    String flightId;
    String airline;
    String departureCity;
    String arrivalCity;
    double price;

    public FlightOption(String id, String airline, String dep, String arr, double price) {
        this.flightId = id;
        this.airline = airline;
        this.departureCity = dep;
        this.arrivalCity = arr;
        this.price = price;
    }
}

class HotelOption {
    String hotelId;
    String name;
    String city;
    double price;
    List<String> amenities;

    public HotelOption(String id, String name, String city, double price, List<String> amenities) {
        this.hotelId = id;
        this.name = name;
        this.city = city;
        this.price = price;
        this.amenities = amenities;
    }
}

class TripComService {
    private final Map<String, FlightOption> flightInventory = new ConcurrentHashMap<>();
    private final Map<String, HotelOption> hotelInventory = new ConcurrentHashMap<>();
    private final Map<String, String> activeBookings = new ConcurrentHashMap<>();

    public List<FlightOption> searchFlights(String origin, String dest) {
        List<FlightOption> res = new ArrayList<>();
        for (FlightOption f : flightInventory.values()) {
            if (f.departureCity.equalsIgnoreCase(origin) && f.arrivalCity.equalsIgnoreCase(dest)) {
                res.add(f);
            }
        }
        return res;
    }

    public synchronized String createBooking(String userId, String flightId, String hotelId) {
        String bId = "BKG_" + UUID.randomUUID().toString().substring(0, 8);
        activeBookings.put(bId, "CONFIRMED");
        return bId;
    }
}

