#include <optional>
#include <algorithm>

struct Flight {
    std::string flightId;
    std::string airline;
    std::string origin;
    std::string destination;
    double price;
    int availableSeats;
};

struct Hotel {
    std::string hotelId;
    std::string name;
    std::string city;
    double pricePerNight;
    std::vector<std::string> amenities;
    int availableRooms;
};

struct BookingRecord {
    std::string bookingId;
    std::string userId;
    std::string flightId;
    std::string hotelId;
    double totalAmount;
    std::string status;
};

class TripComPlatform {
private:
    std::unordered_map<std::string, Flight> flights;
    std::unordered_map<std::string, Hotel> hotels;
    std::unordered_map<std::string, BookingRecord> bookings;

    mutable std::shared_mutex catalogMutex;
    std::mutex bookingMutex;
    int bookingCounter = 1000;

public:
    void addFlight(const Flight& f) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        flights[f.flightId] = f;
    }

    void addHotel(const Hotel& h) {
        std::unique_lock<std::shared_mutex> lock(catalogMutex);
        hotels[h.hotelId] = h;
    }

    std::vector<Flight> searchFlights(const std::string& from, const std::string& to) const {
        std::shared_lock<std::shared_mutex> lock(catalogMutex);
        std::vector<Flight> results;
        for (const auto& [id, f] : flights) {
            if (f.origin == from && f.destination == to && f.availableSeats > 0) {
                results.push_back(f);
            }
        }
        return results;
    }

    std::vector<Hotel> searchHotels(const std::string& city, double maxBudget) const {
        std::shared_lock<std::shared_mutex> lock(catalogMutex);
        std::vector<Hotel> results;
        for (const auto& [id, h] : hotels) {
            if (h.city == city && h.pricePerNight <= maxBudget && h.availableRooms > 0) {
                results.push_back(h);
            }
        }
        return results;
    }

    // Atomic two-phase reservation across Flight & Hotel inventory
    std::optional<std::string> createComboBooking(const std::string& userId, const std::string& flightId, const std::string& hotelId) {
        std::unique_lock<std::shared_mutex> catLock(catalogMutex);
        std::lock_guard<std::mutex> bookLock(bookingMutex);

        auto flightIt = flights.find(flightId);
        auto hotelIt = hotels.find(hotelId);

        if (flightIt == flights.end() || flightIt->second.availableSeats <= 0) {
            std::cout << "Booking Aborted: Flight " << flightId << " has no seats available.\n";
            return std::nullopt;
        }

        if (hotelIt == hotels.end() || hotelIt->second.availableRooms <= 0) {
            std::cout << "Booking Aborted: Hotel " << hotelId << " has no rooms available.\n";
            return std::nullopt;
        }

        // Decrement both inventories atomically
        flightIt->second.availableSeats -= 1;
        hotelIt->second.availableRooms -= 1;

        std::string bId = "BKG_" + std::to_string(++bookingCounter);
        double total = flightIt->second.price + hotelIt->second.pricePerNight;

        bookings[bId] = BookingRecord{bId, userId, flightId, hotelId, total, "CONFIRMED"};
        std::cout << "SUCCESS: Combo Booking " << bId << " confirmed for user " << userId << "! Total: $" << total << "\n";
        return bId;
    }
};

int main() {
    TripComPlatform trip;

    trip.addFlight({"FL_101", "Airways Express", "New York", "London", 250.0, 5});
    trip.addHotel({"HT_501", "The London Grand", "London", 150.0, {"Wi-Fi", "Pool"}, 2});

    std::cout << "--- 1. Searching Flights (New York to London) ---\n";
    auto flights = trip.searchFlights("New York", "London");
    for (const auto& f : flights) {
        std::cout << "Flight: " << f.flightId << " (" << f.airline << ") | Price: $" << f.price << "\n";
    }

    std::cout << "\n--- 2. Searching Hotels in London (< $200) ---\n";
    auto hotels = trip.searchHotels("London", 200.0);
    for (const auto& h : hotels) {
        std::cout << "Hotel: " << h.name << " | Price/Night: $" << h.pricePerNight << "\n";
    }

    std::cout << "\n--- 3. Executing Atomic Combo Reservation ---\n";
    auto bkg = trip.createComboBooking("user_alice", "FL_101", "HT_501");

    return 0;
}

