class LikeService:
    def like_pin(self, user_id, pin_id, pins_db, likes_db):
        if pin_id not in pins_db:
            raise Exception('Pin not found')
        key = (user_id, pin_id)
        if key in likes_db:
            raise Exception('User already liked this pin')
        likes_db[key] = True
        pins_db[pin_id]['like_count'] += 1
        return True

    def unlike_pin(self, user_id, pin_id, pins_db, likes_db):
        key = (user_id, pin_id)
        if key not in likes_db:
            raise Exception('User has not liked this pin')
        del likes_db[key]
        pins_db[pin_id]['like_count'] -= 1
        return True

