import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class Pin {
    String pinId;
    String userId;
    String imageUrl;
    String caption;
    int likeCount;

    public Pin(String pinId, String userId, String imageUrl, String caption) {
        this.pinId = pinId;
        this.userId = userId;
        this.imageUrl = imageUrl;
        this.caption = caption;
        this.likeCount = 0;
    }
}

class PinterestService {
    private final Map<String, Pin> pinRepository = new ConcurrentHashMap<>();
    private final Map<String, Set<String>> followGraph = new ConcurrentHashMap<>();

    public void createPin(Pin pin) {
        pinRepository.put(pin.pinId, pin);
    }

    public void follow(String followerId, String targetUserId) {
        followGraph.computeIfAbsent(followerId, k -> ConcurrentHashMap.newKeySet()).add(targetUserId);
    }

    public List<Pin> getHomeFeed(String userId) {
        List<Pin> feed = new ArrayList<>();
        Set<String> following = followGraph.getOrDefault(userId, Collections.emptySet());
        for (Pin p : pinRepository.values()) {
            if (following.contains(p.userId)) {
                feed.add(p);
            }
        }
        return feed;
    }
}

