#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <memory>
#include <shared_mutex>
#include <mutex>
#include <algorithm>

struct Pin {
    std::string pinId;
    std::string userId;
    std::string imageUrl;
    std::string caption;
    int likeCount = 0;
};

class PinterestPlatform {
private:
    std::unordered_map<std::string, Pin> pins;
    std::unordered_map<std::string, std::unordered_set<std::string>> followers; // userId -> set of followers
    std::unordered_map<std::string, std::unordered_set<std::string>> following; // userId -> set of following
    std::unordered_map<std::string, std::unordered_set<std::string>> userFeedTimeline; // userId -> set of pinIds

    mutable std::shared_mutex pinMutex;
    mutable std::shared_mutex socialMutex;
    int pinCounter = 1000;

public:
    // Fanout-on-Write: When user creates a pin, append to all active followers' timelines
    std::string createPin(const std::string& userId, const std::string& imageUrl, const std::string& caption) {
        std::string pId = "pin_" + std::to_string(++pinCounter);
        Pin newPin{pId, userId, imageUrl, caption, 0};

        {
            std::unique_lock<std::shared_mutex> lock(pinMutex);
            pins[pId] = newPin;
        }

        {
            std::shared_lock<std::shared_mutex> lock(socialMutex);
            auto it = followers.find(userId);
            if (it != followers.end()) {
                for (const auto& followerId : it->second) {
                    userFeedTimeline[followerId].insert(pId);
                }
            }
        }

        std::cout << "[PIN CREATED] " << pId << " by User: " << userId << " fanned out to followers.\n";
        return pId;
    }

    void followUser(const std::string& followerId, const std::string& targetUserId) {
        std::unique_lock<std::shared_mutex> lock(socialMutex);
        following[followerId].insert(targetUserId);
        followers[targetUserId].insert(followerId);
        std::cout << "User " << followerId << " is now following " << targetUserId << "\n";
    }

    void likePin(const std::string& pinId) {
        std::unique_lock<std::shared_mutex> lock(pinMutex);
        auto it = pins.find(pinId);
        if (it != pins.end()) {
            it->second.likeCount++;
            std::cout << "Pin " << pinId << " liked! New count: " << it->second.likeCount << "\n";
        }
    }

    std::vector<Pin> getHomeFeed(const std::string& userId) const {
        std::shared_lock<std::shared_mutex> pLock(pinMutex);
        std::shared_lock<std::shared_mutex> sLock(socialMutex);

        std::vector<Pin> feedResults;
        auto it = userFeedTimeline.find(userId);
        if (it != userFeedTimeline.end()) {
            for (const auto& pId : it->second) {
                auto pIt = pins.find(pId);
                if (pIt != pins.end()) {
                    feedResults.push_back(pIt->second);
                }
            }
        }
        return feedResults;
    }
};

int main() {
    PinterestPlatform pinterest;

    // 1. Social Follow Graph Setup
    pinterest.followUser("user_alice", "creator_bob");
    pinterest.followUser("user_charlie", "creator_bob");

    // 2. Creator Bob posts visual pins (Triggers Fanout-on-Write)
    std::cout << "\n--- Creator Bob posts pins ---\n";
    std::string p1 = pinterest.createPin("creator_bob", "https://cdn.pinterest.com/236x/nordic_home.webp", "Scandinavian Living Room");
    std::string p2 = pinterest.createPin("creator_bob", "https://cdn.pinterest.com/236x/cozy_kitchen.webp", "Minimalist Kitchen Ideas");

    // 3. User Alice views home feed in real-time
    std::cout << "\n--- Fetching Alice's Personalized Feed ---\n";
    auto feed = pinterest.getHomeFeed("user_alice");
    for (const auto& pin : feed) {
        std::cout << "Feed Item: " << pin.caption << " [Image: " << pin.imageUrl << "]\n";
    }

    // 4. Like Pin interaction
    std::cout << "\n--- Liking Pin ---\n";
    pinterest.likePin(p1);

    return 0;
}
